// ─── Supabase Storage helpers ──────────────────────────────────────────────────
// Bucket: "job-photos" — must exist in your Supabase project with RLS allowing
// authenticated uploads. Path convention: {tenantId}/{jobId}/{photoId}.jpg
const STORAGE_BUCKET = "job-photos";

const storageUpload = async (path, blob, accessToken, contentType = "image/jpeg") => {
  const res = await fetch(
    `${SUPABASE_URL}/storage/v1/object/${STORAGE_BUCKET}/${path}`,
    {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": "Bearer " + accessToken,
        "Content-Type": contentType,
        "x-upsert": "true",
      },
      body: blob,
    }
  );
  if (!res.ok) throw new Error("Storage upload failed: " + await res.text());
  return `${SUPABASE_URL}/storage/v1/object/public/${STORAGE_BUCKET}/${path}`;
};

const storageDelete = async (path, accessToken) => {
  await fetch(
    `${SUPABASE_URL}/storage/v1/object/${STORAGE_BUCKET}/${path}`,
    {
      method: "DELETE",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": "Bearer " + accessToken,
      },
    }
  );
};

// Convert a dataUrl (base64) to a Blob for upload
const dataUrlToBlob = (dataUrl) => {
  const [header, data] = dataUrl.split(",");
  const mime = header.match(/:(.*?);/)[1];
  const binary = atob(data);
  const arr = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) arr[i] = binary.charCodeAt(i);
  return new Blob([arr], { type: mime });
};

// Every table that belongs to a specific company — i.e. everything except
// "profiles" (the global user identity, shared across the whole platform)
// and the multi-tenancy tables themselves (tenants/tenant_users/tenant_invites,
// which are how a tenant gets resolved in the first place).
const TENANT_SCOPED_TABLES = [
  "jobs","labor","expenses","vendors","materials","materialsettings","materialstock","customers",
  "crmlogs","zones","crews","rates","homebase","appsettings",
  "historical_jobs","company_settings",
];
// "permissions" is intentionally NOT tenant-scoped — it's a single global
// table (id=1) shared by every company, editable only from Platform Admin.

// ── Auth helpers (Supabase GoTrue REST API, no SDK needed) ──
const AUTH_STORAGE_KEY = "tps_auth_session";

const authSignIn = async (email, password) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/token?grant_type=password", {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email, password }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Login failed");
  return data; // { access_token, refresh_token, user, expires_at, ... }
};

const authRequestPasswordReset = async (email) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/recover", {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ email }),
  });
  if (!res.ok) {
    const data = await res.json().catch(() => ({}));
    throw new Error(data.error_description || data.msg || "Could not send reset email.");
  }
  return true;
};

const authRefresh = async (refreshToken) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/token?grant_type=refresh_token", {
    method: "POST",
    headers: { "apikey": SUPABASE_KEY, "Content-Type": "application/json" },
    body: JSON.stringify({ refresh_token: refreshToken }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error("Session refresh failed");
  return data;
};

const authUpdatePassword = async (accessToken, newPassword) => {
  const res = await fetch(SUPABASE_URL + "/auth/v1/user", {
    method: "PUT",
    headers: {
      "apikey": SUPABASE_KEY,
      "Authorization": "Bearer " + accessToken,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ password: newPassword }),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error_description || data.msg || "Password update failed");
  return data;
};

const saveSession = (session) => {
  try { localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(session)); } catch(e) {}
};
const loadSession = () => {
  try { const s = localStorage.getItem(AUTH_STORAGE_KEY); return s ? JSON.parse(s) : null; } catch(e) { return null; }
};
const clearSession = () => {
  try { localStorage.removeItem(AUTH_STORAGE_KEY); } catch(e) {}
};

// ─── Login View ───────────────────────────────────────────────────────────────
// ─── Set Password View (shown when arriving from an invite/recovery email link) ──
function SetPasswordView({ inviteToken, onSuccess }) {
  const [password,        setPassword]        = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error,           setError]           = useState("");
  const [saving,          setSaving]          = useState(false);

  const handleSetPassword = async (e) => {
    e.preventDefault();
    setError("");
    if (password.length < 6) { setError("Password must be at least 6 characters."); return; }
    if (password !== confirmPassword) { setError("Passwords do not match."); return; }
    setSaving(true);
    try {
      // Grab the user's email BEFORE changing the password, while the invite
      // token's session is still alive.
      const userRes = await fetch(SUPABASE_URL + "/auth/v1/user", {
        headers: { "apikey": SUPABASE_KEY, "Authorization": "Bearer " + inviteToken },
      });
      const userData = await userRes.json();
      if (!userRes.ok || !userData?.email) throw new Error("Could not finish setting up your account. Please ask your owner to resend the invite.");

      // Setting the password invalidates the invite token's session (this is
      // intentional Supabase behavior) — so we must NOT reuse inviteToken
      // after this point for anything.
      await authUpdatePassword(inviteToken, password);

      // Sign in fresh with the new password to get a brand new, valid session.
      const freshSession = await authSignIn(userData.email, password);
      onSuccess(freshSession);
    } catch(err) {
      setError(err.message || "Something went wrong setting your password.");
    }
    setSaving(false);
  };

  return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{maxWidth:340, width:"100%", padding:"0 24px"}}>
        <img src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64} alt="BlacktopIQ"
          style={{width:"100%", maxWidth:340, display:"block", margin:"0 auto 28px"}}/>
        <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Welcome!</h1>
        <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
          Set a password to finish creating your account.
        </p>
        <form onSubmit={handleSetPassword}>
          <label style={S.formLabel}>New Password
            <input type="password" value={password} onChange={e => setPassword(e.target.value)}
              style={S.input} placeholder="At least 6 characters" required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Confirm Password
            <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)}
              style={S.input} placeholder="Re-enter password" required/>
          </label>
          {error && <div style={{color:C.danger, fontSize:13, marginTop:10}}>{error}</div>}
          <button type="submit" style={{...S.btnPrimary, width:"100%", marginTop:18, opacity:saving?0.6:1}} disabled={saving}>
            {saving ? "Setting up..." : "🔑 Set Password & Continue"}
          </button>
        </form>
      </div>
    </div>
  );
}

// ─── Join Company View (redeeming a brand-new-company invite link) ────────────
// Different from SetPasswordView above: that one is for someone Supabase
// already knows about (invited by email into an existing company). This is
// for someone who doesn't have an account yet at all, arriving via a custom
// tenant_invites token, about to create their OWN company from scratch.

// ─── Public Estimate Request Form ─────────────────────────────────────────────
// Accessed via ?request=TENANT_ID — no auth required.
// Fetches tenant branding, collects client info, uploads photos to Supabase
// Storage, then POSTs to /api/submit-request.

const ESTIMATE_REQUEST_SERVICES = [
  "Sealcoating","Crack Fill","Patching","Line Striping",
  "Paving","Milling","Overlay","Mill & Overlay",
  "Infrared Patching","Parking Lot","Other",
];

function EstimateRequestForm({ tenantId }) {
  const [tenantInfo,   setTenantInfo]   = useState(null);
  const [loadingInfo,  setLoadingInfo]  = useState(false); // show form immediately, load branding in background
  const [submitted,    setSubmitted]    = useState(false);
  const [submitting,   setSubmitting]   = useState(false);
  const [error,        setError]        = useState("");

  // Form fields
  const [name,         setName]         = useState("");
  const [phone,        setPhone]        = useState("");
  const [email,        setEmail]        = useState("");
  const [address,      setAddress]      = useState("");
  const [city,         setCity]         = useState("");
  const [stateAbbr,    setStateAbbr]    = useState("");
  const [zip,          setZip]          = useState("");
  const [services,     setServices]     = useState([]);
  const [notes,        setNotes]        = useState("");
  const [photos,       setPhotos]       = useState([]); // [{name, dataUrl}]
  const [captcha,      setCaptcha]      = useState(false);
  const [uploading,    setUploading]    = useState(false);

  // Load tenant branding — always show form even if fetch fails
  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetch("/api/public?action=tenant-public&id=" + tenantId);
        if (res.ok) {
          const data = await res.json();
          setTenantInfo(data);
        }
        // If fetch fails (404, network error) — just show form with defaults
      } catch(e) {}
      finally { setLoadingInfo(false); }
    };
    // Short timeout so form appears even if API is slow
    const t = setTimeout(() => setLoadingInfo(false), 3000);
    load().finally(() => clearTimeout(t));
  }, [tenantId]);

  const toggleService = (s) =>
    setServices(prev => prev.includes(s) ? prev.filter(x=>x!==s) : [...prev, s]);

  const handlePhotos = (files) => {
    Array.from(files).slice(0, 5).forEach(file => {
      if (file.size > 10*1024*1024) return;
      const reader = new FileReader();
      reader.onload = e => setPhotos(prev => [...prev.slice(0,4), {name:file.name, dataUrl:e.target.result}]);
      reader.readAsDataURL(file);
    });
  };

  const handleSubmit = async () => {
    setError("");
    if (!name.trim()) { setError("Please enter your name."); return; }
    if (!phone.trim() && !email.trim()) { setError("Please enter a phone number or email address."); return; }
    if (!address.trim()) { setError("Please enter a street address."); return; }
    if (services.length === 0) { setError("Please select at least one service."); return; }
    if (!captcha) { setError("Please check the box to confirm you're not a robot."); return; }

    setSubmitting(true);
    try {
      const res = await fetch("/api/public?action=submit-request", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          tenantId, name: name.trim(), phone: phone.trim(), email: email.trim(),
          address: address.trim(), city: city.trim(), state: stateAbbr.trim(), zip: zip.trim(),
          services, notes: notes.trim(), photos,
        }),
      });
      const data = await res.json();
      if (!res.ok) { setError(data.error || "Submission failed. Please try again."); setSubmitting(false); return; }
      setSubmitted(true);
    } catch(e) {
      setError("Network error. Please try again.");
      setSubmitting(false);
    }
  };

  const brand = {
    accent: tenantInfo?.accentColor || "#f0ab2e",
    name:   tenantInfo?.companyName || "",
    logo:   tenantInfo?.logoB64     || null,
  };

  if (loadingInfo) return (
    <div style={{minHeight:"100svh", display:"flex", alignItems:"center", justifyContent:"center", background:"#f3f4f6"}}>
      <div style={{fontSize:14, color:"#6b7280"}}>Loading...</div>
    </div>
  );

  if (submitted) return (
    <div style={{minHeight:"100svh", display:"flex", alignItems:"center", justifyContent:"center", background:"#f3f4f6", padding:24}}>
      <div style={{background:"#fff", borderRadius:16, padding:40, maxWidth:480, width:"100%", textAlign:"center", boxShadow:"0 4px 24px rgba(0,0,0,0.08)"}}>
        {brand.logo && <img src={"data:image/png;base64,"+brand.logo} alt={brand.name} style={{maxWidth:200, maxHeight:70, objectFit:"contain", margin:"0 auto 24px", display:"block"}}/>}
        <div style={{fontSize:48, marginBottom:16}}>✅</div>
        <h2 style={{fontSize:22, fontWeight:700, marginBottom:12}}>Request Received!</h2>
        <p style={{fontSize:14, color:"#6b7280", lineHeight:1.6}}>
          Thank you, <strong>{name}</strong>. We've received your estimate request and will be in touch soon.
        </p>
        <p style={{fontSize:13, color:"#9ca3af", marginTop:16}}>{brand.name ? `— ${brand.name}` : ""}</p>
      </div>
    </div>
  );

  return (
    <div style={{minHeight:"100svh", background:"#f3f4f6", padding:"24px 16px"}}>
      <div style={{maxWidth:560, margin:"0 auto"}}>

        {/* Header */}
        <div style={{textAlign:"center", marginBottom:24}}>
          {brand.logo
            ? <img src={"data:image/png;base64,"+brand.logo} alt={brand.name} style={{maxWidth:220, maxHeight:80, objectFit:"contain", margin:"0 auto 12px", display:"block"}}/>
            : brand.name
              ? <div style={{fontSize:22, fontWeight:700, marginBottom:12}}>{brand.name}</div>
              : <div style={{height:40, marginBottom:12}}/> /* placeholder while loading */
          }
          <h1 style={{fontSize:20, fontWeight:700, margin:"0 0 4px"}}>Request a Free Estimate</h1>
          <p style={{fontSize:13, color:"#6b7280", margin:0}}>Fill out the form below and we'll get back to you shortly.</p>
        </div>

        <div style={{background:"#fff", borderRadius:12, padding:24, boxShadow:"0 2px 12px rgba(0,0,0,0.06)", display:"flex", flexDirection:"column", gap:16}}>

          {/* Contact info */}
          <div>
            <div style={{fontSize:12, fontWeight:700, color:"#6b7280", letterSpacing:"0.05em", textTransform:"uppercase", marginBottom:10}}>Your Info</div>
            <div style={{display:"grid", gridTemplateColumns:"1fr 1fr", gap:10}}>
              <label style={{display:"flex", flexDirection:"column", gap:4, fontSize:13, color:"#374151", gridColumn:"1/-1"}}>
                Full Name *
                <input value={name} onChange={e=>setName(e.target.value)} placeholder="Jane Smith"
                  style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box"}}/>
              </label>
              <label style={{display:"flex", flexDirection:"column", gap:4, fontSize:13, color:"#374151"}}>
                Phone
                <input value={phone} onChange={e=>setPhone(e.target.value)} placeholder="(555) 555-5555" type="tel"
                  style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box"}}/>
              </label>
              <label style={{display:"flex", flexDirection:"column", gap:4, fontSize:13, color:"#374151"}}>
                Email
                <input value={email} onChange={e=>setEmail(e.target.value)} placeholder="jane@example.com" type="email"
                  style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box"}}/>
              </label>
              <div style={{gridColumn:"1/-1", fontSize:11, color:"#9ca3af"}}>* Phone or email required</div>
            </div>
          </div>

          {/* Address */}
          <div>
            <div style={{fontSize:12, fontWeight:700, color:"#6b7280", letterSpacing:"0.05em", textTransform:"uppercase", marginBottom:10}}>Service Address</div>
            <div style={{display:"flex", flexDirection:"column", gap:8}}>
              <input value={address} onChange={e=>setAddress(e.target.value)} placeholder="Street Address *"
                style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box"}}/>
              <div style={{display:"grid", gridTemplateColumns:"2fr 1fr 1fr", gap:8}}>
                <input value={city} onChange={e=>setCity(e.target.value)} placeholder="City"
                  style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box"}}/>
                <input value={stateAbbr} onChange={e=>setStateAbbr(e.target.value)} placeholder="State" maxLength={2}
                  style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box"}}/>
                <input value={zip} onChange={e=>setZip(e.target.value)} placeholder="ZIP"
                  style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box"}}/>
              </div>
            </div>
          </div>

          {/* Services */}
          <div>
            <div style={{fontSize:12, fontWeight:700, color:"#6b7280", letterSpacing:"0.05em", textTransform:"uppercase", marginBottom:10}}>Services Needed *</div>
            <div style={{display:"flex", flexWrap:"wrap", gap:8}}>
              {ESTIMATE_REQUEST_SERVICES.map(s => (
                <button key={s}
                  onClick={() => toggleService(s)}
                  style={{
                    fontSize:13, padding:"6px 14px", borderRadius:20, cursor:"pointer", border:"none",
                    background: services.includes(s) ? brand.accent : "#f3f4f6",
                    color: services.includes(s) ? "#000" : "#374151",
                    fontWeight: services.includes(s) ? 700 : 400,
                  }}>
                  {s}
                </button>
              ))}
            </div>
          </div>

          {/* Notes */}
          <div>
            <div style={{fontSize:12, fontWeight:700, color:"#6b7280", letterSpacing:"0.05em", textTransform:"uppercase", marginBottom:10}}>Description / Notes</div>
            <textarea value={notes} onChange={e=>setNotes(e.target.value)}
              placeholder="Describe what you need, approximate size, any special considerations..."
              style={{border:"1px solid #e5e7eb", borderRadius:6, padding:"9px 10px", fontSize:14, outline:"none", width:"100%", boxSizing:"border-box", minHeight:90, resize:"vertical"}}/>
          </div>

          {/* Photos */}
          <div>
            <div style={{fontSize:12, fontWeight:700, color:"#6b7280", letterSpacing:"0.05em", textTransform:"uppercase", marginBottom:10}}>Photos (optional, up to 5)</div>
            <label style={{display:"block", border:"2px dashed #e5e7eb", borderRadius:8, padding:"16px", textAlign:"center", cursor:"pointer", fontSize:13, color:"#6b7280"}}>
              📸 Tap to add photos
              <input type="file" accept="image/*" multiple style={{display:"none"}} onChange={e=>handlePhotos(e.target.files)}/>
            </label>
            {photos.length > 0 && (
              <div style={{display:"flex", gap:8, flexWrap:"wrap", marginTop:10}}>
                {photos.map((p,i) => (
                  <div key={i} style={{position:"relative"}}>
                    <img src={p.dataUrl} alt={p.name} style={{width:72, height:72, objectFit:"cover", borderRadius:6, border:"1px solid #e5e7eb"}}/>
                    <button onClick={() => setPhotos(prev => prev.filter((_,j)=>j!==i))}
                      style={{position:"absolute", top:-6, right:-6, background:"#ef4444", color:"#fff", border:"none", borderRadius:"50%", width:18, height:18, fontSize:10, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center"}}>✕</button>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Captcha */}
          <label style={{display:"flex", alignItems:"center", gap:10, cursor:"pointer", fontSize:13, color:"#374151", border:"1px solid #e5e7eb", borderRadius:8, padding:"12px 14px"}}>
            <div onClick={() => setCaptcha(v=>!v)}
              style={{width:22, height:22, borderRadius:4, border:`2px solid ${captcha ? brand.accent : "#d1d5db"}`, background: captcha ? brand.accent : "#fff", display:"flex", alignItems:"center", justifyContent:"center", flexShrink:0, cursor:"pointer"}}>
              {captcha && <span style={{color:"#000", fontSize:14, fontWeight:700}}>✓</span>}
            </div>
            I'm not a robot
          </label>

          {/* Error */}
          {error && <div style={{fontSize:13, color:"#ef4444", background:"#fef2f2", borderRadius:6, padding:"10px 14px"}}>{error}</div>}

          {/* Submit */}
          <button onClick={handleSubmit} disabled={submitting}
            style={{background: brand.accent, color:"#000", fontWeight:700, fontSize:15, border:"none", borderRadius:10, padding:"14px", cursor: submitting ? "not-allowed" : "pointer", opacity: submitting ? 0.6 : 1}}>
            {submitting ? "Submitting..." : "Submit Estimate Request"}
          </button>
        </div>

        <p style={{textAlign:"center", fontSize:11, color:"#9ca3af", marginTop:16}}>Powered by BlacktopIQ</p>
      </div>
    </div>
  );
}

function JoinCompanyView({ token, onSuccess }) {
  const [companyName, setCompanyName] = useState("");
  const [phone,        setPhone]        = useState("");
  const [email,        setEmail]        = useState("");
  const [password,     setPassword]     = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error,        setError]        = useState("");
  const [saving,       setSaving]       = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (!companyName.trim()) { setError("Company name is required."); return; }
    if (!phone.trim()) { setError("Phone number is required."); return; }
    if (!email.trim()) { setError("Email is required."); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())) { setError("Enter a valid email address (e.g. name@company.com)."); return; }
    if (password.length < 8) { setError("Password must be at least 8 characters."); return; }
    if (password !== confirmPassword) { setError("Passwords do not match."); return; }
    setSaving(true);
    try {
      const res = await fetch("/api/team?action=redeem-tenant-invite", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token, email: email.trim(), password, companyName: companyName.trim(), phone: phone.trim() }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Could not set up your company.");

      // Account + company now exist server-side — sign in for real to get a
      // proper session, same as any normal login.
      const freshSession = await authSignIn(email.trim(), password);
      onSuccess(freshSession);
    } catch(err) {
      setError(err.message || "Something went wrong setting up your company.");
    }
    setSaving(false);
  };

  return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{maxWidth:380, width:"100%", padding:"0 24px"}}>
        <img src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64} alt="BlacktopIQ"
          style={{width:"100%", maxWidth:340, display:"block", margin:"0 auto 30px"}}/>
        <h1 style={{...S.h1, textAlign:"center", marginBottom:6}}>Welcome to BlacktopIQ</h1>
        <p style={{fontSize:13, color:C.textMuted, textAlign:"center", marginBottom:20}}>
          Set up your company and create your admin account.
        </p>
        <form onSubmit={handleSubmit}>
          <label style={S.formLabel}>Company Name
            <input value={companyName} onChange={e => setCompanyName(e.target.value)} style={S.input} placeholder="e.g. Smith Paving Co." required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Phone *
            <input type="tel" value={phone} onChange={e => setPhone(formatPhone(e.target.value))} style={S.input} required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Your Email
            <input type="email" value={email} onChange={e => setEmail(e.target.value)} style={S.input} required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Password
            <input type="password" value={password} onChange={e => setPassword(e.target.value)} style={S.input} placeholder="At least 8 characters" required/>
          </label>
          <label style={{...S.formLabel, marginTop:12}}>Confirm Password
            <input type="password" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} style={S.input} required/>
          </label>
          {error && <div style={{color:C.danger, fontSize:13, marginTop:10}}>{error}</div>}
          <button type="submit" style={{...S.btnPrimary, width:"100%", marginTop:18, opacity:saving?0.6:1}} disabled={saving}>
            {saving ? "Setting up your company..." : "🚀 Create My Company"}
          </button>
        </form>
      </div>
    </div>
  );
}



// ─── Company Settings View (owner only) ────────────────────────────────────
function CompanySettingsView({ setView, companySettings, syncCompanySettings }) {
  const cs = companySettings || {};
  const [name,     setName]     = useState(cs.name||"");
  const [phone,    setPhone]    = useState(formatPhone(cs.phone||""));
  const [email,    setEmail]    = useState(cs.email||"");
  const [website,  setWebsite]  = useState(cs.website||"");
  const [street,   setStreet]   = useState(cs.street||"");
  const [city,     setCity]     = useState(cs.city||"");
  const [state_,   setState_]   = useState(cs.state||"PA");
  const [zip,      setZip]      = useState(cs.zip||"");
  const [logoB64,  setLogoB64]  = useState(cs.logoB64||"");
  const [logoName, setLogoName] = useState("");
  const [legalTerms,   setLegalTerms]   = useState(cs.legalTerms||"");
  const [depositTerms, setDepositTerms] = useState(cs.depositTerms||"A 25% deposit is required to schedule work. Balance due upon completion.");
  const [googleReviewUrl, setGoogleReviewUrl] = useState(cs.googleReviewUrl||"");
  const [accentColor, setAccentColor] = useState(cs.accentColor || DEFAULT_ACCENT);
  const [headerColor, setHeaderColor] = useState(cs.headerColor || DEFAULT_HEADER);
  const [extractedColors, setExtractedColors] = useState([]);
  const [saving,  setSaving]  = useState(false);
  const [message, setMessage] = useState("");

  // companySettings can still be the empty default when this view mounts,
  // if the async load hasn't resolved yet. Re-sync the form once real data
  // arrives so a Save click can't write blanks over good DB data.
  const hydrated = useRef(false);
  useEffect(() => {
    if (hydrated.current) return;
    if (companySettings && companySettings.name) {
      setName(companySettings.name || "");
      setPhone(formatPhone(companySettings.phone || ""));
      setEmail(companySettings.email || "");
      setWebsite(companySettings.website || "");
      setStreet(companySettings.street || "");
      setCity(companySettings.city || "");
      setState_(companySettings.state || "PA");
      setZip(companySettings.zip || "");
      setLegalTerms(companySettings.legalTerms || "");
      setDepositTerms(companySettings.depositTerms || "A 25% deposit is required to schedule work. Balance due upon completion.");
      setGoogleReviewUrl(companySettings.googleReviewUrl || "");
      setAccentColor(companySettings.accentColor || DEFAULT_ACCENT);
      setHeaderColor(companySettings.headerColor || DEFAULT_HEADER);
      hydrated.current = true;
    }
  }, [companySettings]);

  const handleLogo = (e) => {
    const file = e.target.files[0]; if (!file) return;
    if (file.size > 5*1024*1024) { setMessage("⚠️ Logo must be under 5 MB."); return; }
    const reader = new FileReader();
    reader.onload = ev => {
      const b64 = ev.target.result.split(",")[1];
      setLogoB64(b64);
      setLogoName(file.name);
      // Extract dominant colors from the new logo
      const img = new Image();
      img.onload = () => {
        const colors = extractColorsFromImage(img, 6);
        setExtractedColors(colors);
      };
      img.src = ev.target.result;
    };
    reader.readAsDataURL(file);
  };

  // Extract colors from existing logo on mount
  useEffect(() => {
    const b64 = cs.logoB64;
    if (!b64 || extractedColors.length > 0) return;
    const img = new Image();
    img.onload = () => setExtractedColors(extractColorsFromImage(img, 6));
    img.src = "data:image/png;base64," + b64;
  }, [cs.logoB64]);

  const save = async () => {
    if (!name.trim()) { setMessage("⚠️ Company name is required."); return; }
    setSaving(true); setMessage("");
    const csData = {
      name:name.trim(), phone:phone.trim(), email:email.trim(), website:website.trim(),
      street:street.trim(), city:city.trim(), state:state_.trim(), zip:zip.trim(),
      logoB64: logoB64||cs.logoB64||"", legalTerms:legalTerms.trim(), depositTerms:depositTerms.trim(),
      googleReviewUrl: googleReviewUrl.trim(),
      accentColor, headerColor,
    };
    await syncCompanySettings(csData);
    setMessage("✅ Company settings saved.");
    setSaving(false);
  };

  return (
    <div style={S.page}>
      <div style={S.pageHeader}>
        <h1 style={S.h1}>Company Settings</h1>
        <button style={S.btnSecondary} onClick={()=>setView("owner-hub")}>← Owner Hub</button>
      </div>
      <p style={S.subhead}>This information appears on all estimates, invoices, and PDFs.</p>
      <section style={S.section}>
        <h2 style={S.h2}>Company Info</h2>
        <label style={S.formLabel}>Company Name *<input type="text" value={name} onChange={e=>setName(e.target.value)} style={S.input}/></label>
        <div style={{...S.formGrid,marginTop:10}}>
          <label style={S.formLabel}>Phone<input type="tel" value={phone} onChange={e=>setPhone(formatPhone(e.target.value))} style={S.input}/></label>
          <label style={S.formLabel}>Estimate Email<input type="email" value={email} onChange={e=>setEmail(e.target.value)} style={S.input} autoCapitalize="none"/></label>
        </div>
        <label style={{...S.formLabel,marginTop:10}}>Website<input type="url" value={website} onChange={e=>setWebsite(e.target.value)} style={S.input}/></label>
        <label style={{...S.formLabel,marginTop:10}}>Google Review Link
          <span style={{fontSize:11, color:C.textDim, fontWeight:400}}> (optional — included in review request texts/emails to clients)</span>
          <input type="url" value={googleReviewUrl} onChange={e=>setGoogleReviewUrl(e.target.value)} style={S.input} placeholder="https://g.page/r/.../review"/>
        </label>
      </section>
      <section style={S.section}>
        <h2 style={S.h2}>Company Address</h2>
        <label style={S.formLabel}>Street<input type="text" value={street} onChange={e=>setStreet(e.target.value)} style={S.input}/></label>
        <div style={{...S.formGrid,marginTop:10}}>
          <label style={S.formLabel}>City<input type="text" value={city} onChange={e=>setCity(e.target.value)} style={S.input}/></label>
          <label style={S.formLabel}>State<input type="text" value={state_} onChange={e=>setState_(e.target.value)} style={S.input} maxLength={2}/></label>
        </div>
        <label style={{...S.formLabel,marginTop:10}}>ZIP<input type="text" value={zip} onChange={e=>setZip(e.target.value)} style={S.input} maxLength={10}/></label>
      </section>
      <section style={S.section}>
        <h2 style={S.h2}>Logo</h2>
        {(logoB64||cs.logoB64) && <img src={"data:image/png;base64,"+(logoB64||cs.logoB64)} alt="Logo" style={{maxWidth:200,maxHeight:80,display:"block",marginBottom:10}}/>}
        <input type="file" accept="image/png,image/jpeg,image/gif,image/webp" onChange={handleLogo} style={{display:"block",fontSize:13,marginBottom:4}}/>
        {logoName && <p style={{fontSize:12,color:C.green}}>✅ New logo: {logoName}</p>}
        <p style={{fontSize:11,color:C.textDim}}>PNG recommended, under 500 KB.</p>
      </section>

      <section style={S.section}>
        <h2 style={S.h2}>Brand Colors</h2>
        <p style={{fontSize:12, color:C.textMuted, marginBottom:14}}>
          These colors appear on your estimates, invoices, and PDFs.
        </p>

        {/* Live preview strip */}
        <div style={{borderRadius:8, overflow:"hidden", marginBottom:16, boxShadow:C.shadow}}>
          <div style={{background:headerColor, padding:"12px 20px", display:"flex", alignItems:"center", justifyContent:"space-between"}}>
            <span style={{color:accentColor, fontWeight:800, fontSize:16, letterSpacing:"0.04em"}}>ESTIMATE</span>
            <span style={{color:"#ffffff", fontSize:12, opacity:0.7}}>Preview</span>
          </div>
          <div style={{background:"#ffffff", padding:"10px 20px", borderBottom:`3px solid ${accentColor}`}}>
            <span style={{color:accentColor, fontWeight:700, fontSize:13}}>Total: $1,250.00</span>
          </div>
        </div>

        <div style={{display:"flex", gap:24, flexWrap:"wrap"}}>
          {/* Accent color */}
          <div style={{flex:1, minWidth:160}}>
            <label style={{...S.formLabel, marginBottom:6}}>
              Accent Color
              <span style={{fontSize:11, color:C.textDim, fontWeight:400}}> (rule line, totals, highlights)</span>
            </label>
            <div style={{display:"flex", alignItems:"center", gap:10}}>
              <input type="color" value={accentColor} onChange={e => setAccentColor(e.target.value)}
                style={{width:44, height:36, border:`1px solid ${C.border}`, borderRadius:6, cursor:"pointer", padding:2}}/>
              <input type="text" value={accentColor} onChange={e => setAccentColor(e.target.value)}
                style={{...S.input, width:90, fontFamily:"monospace", fontSize:13}}
                placeholder="#f0ab2e"/>
              <button style={{...S.btnSecondary, fontSize:12, padding:"6px 10px"}}
                onClick={() => setAccentColor(DEFAULT_ACCENT)}>Reset</button>
            </div>
          </div>

          {/* Header background color */}
          <div style={{flex:1, minWidth:160}}>
            <label style={{...S.formLabel, marginBottom:6}}>
              Header Background
              <span style={{fontSize:11, color:C.textDim, fontWeight:400}}> (top bar on PDFs)</span>
            </label>
            <div style={{display:"flex", alignItems:"center", gap:10}}>
              <input type="color" value={headerColor} onChange={e => setHeaderColor(e.target.value)}
                style={{width:44, height:36, border:`1px solid ${C.border}`, borderRadius:6, cursor:"pointer", padding:2}}/>
              <input type="text" value={headerColor} onChange={e => setHeaderColor(e.target.value)}
                style={{...S.input, width:90, fontFamily:"monospace", fontSize:13}}
                placeholder="#1a1a1a"/>
              <button style={{...S.btnSecondary, fontSize:12, padding:"6px 10px"}}
                onClick={() => setHeaderColor(DEFAULT_HEADER)}>Reset</button>
            </div>
          </div>
        </div>

        {/* Extracted colors from logo */}
        {extractedColors.length > 0 && (
          <div style={{marginTop:16}}>
            <div style={{fontSize:12, color:C.textMuted, marginBottom:8, fontWeight:600}}>
              🎨 Colors from your logo — click to use:
            </div>
            <div style={{display:"flex", gap:8, flexWrap:"wrap"}}>
              {extractedColors.map(color => (
                <div key={color} style={{display:"flex", flexDirection:"column", alignItems:"center", gap:4}}>
                  <div
                    style={{width:36, height:36, borderRadius:6, background:color, cursor:"pointer",
                      border:`2px solid ${color === accentColor || color === headerColor ? C.text : C.border}`,
                      boxShadow: color === accentColor || color === headerColor ? `0 0 0 2px ${C.text}` : "none"}}
                    title={color}
                    onClick={() => {
                      // First click sets accent, second click sets header
                      if (accentColor === DEFAULT_ACCENT || accentColor === color) {
                        setAccentColor(color);
                      } else {
                        setHeaderColor(color);
                      }
                    }}
                  />
                  <span style={{fontSize:9, color:C.textDim, fontFamily:"monospace"}}>{color}</span>
                </div>
              ))}
            </div>
            <div style={{fontSize:11, color:C.textDim, marginTop:8}}>
              Click a swatch to set as accent color. Click a second swatch to set as header background.
            </div>
          </div>
        )}
        {!(logoB64||cs.logoB64) && (
          <div style={{fontSize:12, color:C.textDim, marginTop:8}}>
            Upload a logo above to automatically extract your brand colors.
          </div>
        )}
      </section>
      <section style={S.section}>
        <h2 style={S.h2}>Legal Terms</h2>
        <p style={{fontSize:12,color:C.textMuted,marginBottom:8}}><strong>Required before sending estimates.</strong> These appear at the bottom of every estimate PDF.</p>
        <textarea value={legalTerms} onChange={e=>setLegalTerms(e.target.value)}
          style={{...S.input,height:120,resize:"vertical",fontFamily:"inherit",fontSize:12}}
          placeholder="Estimate given before work commenced. Workmanship is guaranteed for 30 days..."/>
        <label style={{...S.formLabel,marginTop:12}}>Deposit / Scheduling Terms
          <textarea value={depositTerms} onChange={e=>setDepositTerms(e.target.value)}
            style={{...S.input,height:60,resize:"vertical",fontFamily:"inherit",fontSize:12}}/>
        </label>
      </section>
      {message && <div style={{fontSize:13,color:message.startsWith("⚠️")?C.danger:C.green,padding:"0 16px 12px"}}>{message}</div>}
      <div style={{padding:"0 16px 24px"}}>
        <button style={{...S.btnPrimary,width:"100%",opacity:saving?0.6:1}} onClick={save} disabled={saving}>
          {saving?"Saving...":<><LucideIcons.Save size={15} strokeWidth={2} style={{verticalAlign:"middle",marginRight:5}}/> Save Company Settings</>}
        </button>
      </div>
    </div>
  );
}

// ─── Referral View (owner only) ─────────────────────────────────────────────
function EstimateRequestLinkView({ setView, currentTenantId }) {
  const requestUrl = window.location.origin + "/?request=" + currentTenantId;
  const [copied,   setCopied]   = useState(false);
  const [qrDataUrl, setQrDataUrl] = useState("");
  const canvasRef = useRef(null);

  // Generate QR code using qrcode.js loaded from CDN
  useEffect(() => {
    const generate = async () => {
      try {
        // Dynamically load qrcode library if not already present
        if (!window.QRCode) {
          await new Promise((resolve, reject) => {
            const script = document.createElement("script");
            script.src = "https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js";
            script.onload = resolve;
            script.onerror = reject;
            document.head.appendChild(script);
          });
        }
        // Render into a temp div then grab the canvas data URL
        const div = document.createElement("div");
        document.body.appendChild(div);
        new window.QRCode(div, {
          text: requestUrl, width: 256, height: 256,
          colorDark: "#000000", colorLight: "#ffffff",
          correctLevel: window.QRCode.CorrectLevel.M,
        });
        // QRCode renders a canvas or img — get the data URL
        setTimeout(() => {
          const canvas = div.querySelector("canvas");
          const img    = div.querySelector("img");
          if (canvas) setQrDataUrl(canvas.toDataURL("image/png"));
          else if (img) setQrDataUrl(img.src);
          document.body.removeChild(div);
        }, 100);
      } catch(e) {
        console.error("QR generation failed:", e);
      }
    };
    generate();
  }, [requestUrl]);

  const copy = () => {
    navigator.clipboard.writeText(requestUrl).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  const downloadQR = () => {
    if (!qrDataUrl) return;
    const a = document.createElement("a");
    a.href = qrDataUrl;
    a.download = "blacktopiq-request-qr.png";
    a.click();
  };

  return (
    <div className="tps-page" style={S.page}>
      <h1 style={S.h1}><LucideIcons.ClipboardList size={16} strokeWidth={2} style={{verticalAlign:"middle",marginRight:6}}/> Estimate Request Form</h1>
      <p style={S.subhead}>Share this link or QR code with clients so they can submit an estimate request directly to you — no account needed.</p>

      <section style={S.section}>
        <h2 style={S.h2}>Your Request Form Link</h2>
        <div style={{display:"flex", gap:8, alignItems:"center", flexWrap:"wrap"}}>
          <input readOnly value={requestUrl}
            style={{...S.input, flex:1, minWidth:0, fontSize:12, background:C.surface2, color:C.textMuted}}/>
          <button style={{...S.btnPrimary, flexShrink:0}} onClick={copy}>
            {copied ? "✓ Copied!" : "📋 Copy Link"}
          </button>
        </div>
        <div style={{fontSize:12, color:C.textMuted, marginTop:8}}>
          Add this link to your website, email signature, Google Business profile, or social media.
        </div>
      </section>

      <section style={S.section}>
        <h2 style={S.h2}>QR Code</h2>
        <p style={{fontSize:13, color:C.textMuted, marginBottom:12}}>Print this and leave it at job sites, on your truck, or hand it to potential customers.</p>
        <div style={{textAlign:"center"}}>
          {qrDataUrl
            ? <img src={qrDataUrl} alt="QR Code" style={{width:200, height:200, borderRadius:8, border:`1px solid ${C.border}`}}/>
            : <div style={{width:200, height:200, background:C.surface2, borderRadius:8, border:`1px solid ${C.border}`, display:"flex", alignItems:"center", justifyContent:"center", margin:"0 auto", fontSize:12, color:C.textMuted}}>Generating...</div>
          }
        </div>
        <div style={{textAlign:"center", marginTop:12}}>
          <button onClick={downloadQR} disabled={!qrDataUrl}
            style={{...S.btnSecondary, fontSize:13, opacity: qrDataUrl ? 1 : 0.4}}>
            ⬇ Download QR Code
          </button>
        </div>
      </section>

      <section style={S.section}>
        <h2 style={S.h2}>How It Works</h2>
        <div style={{display:"flex", flexDirection:"column", gap:10, fontSize:13, color:C.text}}>
          {[
            ["1️⃣", "Client scans the QR code or visits your link"],
            ["2️⃣", "They fill out their name, address, services needed, and can add photos"],
            ["3️⃣", "Their request appears as a new job in your Jobs pipeline with status 'Estimate'"],
            ["4️⃣", "You review, add measurements, and send them an estimate"],
          ].map(([num, text]) => (
            <div key={num} style={{display:"flex", gap:10, alignItems:"flex-start"}}>
              <span style={{fontSize:18, flexShrink:0}}>{num}</span>
              <span>{text}</span>
            </div>
          ))}
        </div>
      </section>
    </div>
  );
}


