const SUPABASE_URL_ADMIN = "https://elzymtqlcceouftwhcdk.supabase.co";
const SUPABASE_KEY_ADMIN = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImVsenltdHFsY2Nlb3VmdHdoY2RrIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODA1MDk3MDYsImV4cCI6MjA5NjA4NTcwNn0.rTr3e4739fJpbHXgBneRTr18utum5XxMWTf2E0DtOVQ";

function AdminApp() {
  const [adminSession,   setAdminSession]   = useState(null);
  const [adminChecked,   setAdminChecked]   = useState(false);
  const [isSuperAdmin,   setIsSuperAdmin]   = useState(false);
  const [adminEmail,     setAdminEmail]     = useState("");
  const [adminPassword,  setAdminPassword]  = useState("");
  const [loginError,     setLoginError]     = useState("");
  const [loggingIn,      setLoggingIn]      = useState(false);
  const [adminUsers,     setAdminUsers]     = useState([]);
  const [newAdminEmail,  setNewAdminEmail]  = useState("");
  const [addingAdmin,    setAddingAdmin]    = useState(false);
  const [addAdminError,  setAddAdminError]  = useState("");
  const [permissions,    setPermissions]    = useState(DEFAULT_PERMISSIONS);
  const sbH = (token) => ({
    "apikey": SUPABASE_KEY_ADMIN,
    "Authorization": "Bearer " + (token || SUPABASE_KEY_ADMIN),
    "Content-Type": "application/json",
  });

  // Check existing session
  useEffect(() => {
    (async () => {
      try {
        const res = await fetch(SUPABASE_URL_ADMIN + "/auth/v1/user", {
          headers: { "apikey": SUPABASE_KEY_ADMIN, "Authorization": "Bearer " + (localStorage.getItem("adminToken")||"") }
        });
        if (res.ok) {
          const data = await res.json();
          if (data?.id) {
            await verifyAndSetAdmin(data, localStorage.getItem("adminToken"));
            return;
          }
        }
      } catch(e) {}
      setAdminChecked(true);
    })();
  }, []);

  const verifyAndSetAdmin = async (userData, token) => {
    // Check platform_admins
    const r = await fetch(SUPABASE_URL_ADMIN + "/rest/v1/platform_admins?user_id=eq." + userData.id + "&select=user_id,is_super", {
      headers: sbH(token)
    });
    const data = await r.json();
    if (!Array.isArray(data) || data.length === 0) {
      setLoginError("Access denied. You are not a platform admin.");
      setAdminChecked(true);
      return false;
    }
    setAdminSession({ user: userData, access_token: token });
    setIsSuperAdmin(data[0]?.is_super === true);
    setAdminChecked(true);
    await loadAdminUsers(token);
    return true;
  };

  const loadAdminUsers = async (token) => {
    try {
      const r = await fetch(SUPABASE_URL_ADMIN + "/rest/v1/platform_admins?select=user_id,is_super", {
        headers: sbH(token)
      });
      const admins = await r.json();
      if (!Array.isArray(admins)) return;
      // Get profile info for each admin
      const ids = admins.map(a => a.user_id).join(",");
      const pr = await fetch(SUPABASE_URL_ADMIN + "/rest/v1/profiles?id=in.(" + ids + ")&select=id,first_name,last_name,email", {
        headers: sbH(token)
      });
      const profiles = await pr.json();
      const merged = admins.map(a => {
        const p = Array.isArray(profiles) ? profiles.find(x => x.id === a.user_id) : null;
        return { ...a, name: p ? [p.first_name, p.last_name].filter(Boolean).join(" ") : "", email: p?.email || "" };
      });
      setAdminUsers(merged);
    } catch(e) { console.error("loadAdminUsers error:", e); }
  };

  const login = async () => {
    setLoggingIn(true); setLoginError("");
    try {
      const res = await fetch(SUPABASE_URL_ADMIN + "/auth/v1/token?grant_type=password", {
        method: "POST",
        headers: { "apikey": SUPABASE_KEY_ADMIN, "Content-Type": "application/json" },
        body: JSON.stringify({ email: adminEmail.trim(), password: adminPassword }),
      });
      const data = await res.json();
      if (!res.ok) { setLoginError((data.error_description || data.msg || data.error || "Login failed.") + " (status " + res.status + ")"); setLoggingIn(false); return; }
      localStorage.setItem("adminToken", data.access_token);
      const ok = await verifyAndSetAdmin(data.user, data.access_token);
      if (!ok) localStorage.removeItem("adminToken");
    } catch(e) { setLoginError("Error: " + e.message); }
    setLoggingIn(false);
  };

  const logout = () => {
    localStorage.removeItem("adminToken");
    setAdminSession(null);
    setAdminChecked(false);
    setTimeout(() => setAdminChecked(true), 100);
  };

  const addAdmin = async () => {
    if (!newAdminEmail.trim()) { setAddAdminError("Email required."); return; }
    setAddingAdmin(true); setAddAdminError("");
    try {
      // Look up user by email from profiles
      const r = await fetch(SUPABASE_URL_ADMIN + "/rest/v1/profiles?email=eq." + encodeURIComponent(newAdminEmail.trim()) + "&select=id,first_name,last_name,email", {
        headers: sbH(adminSession.access_token)
      });
      const users = await r.json();
      if (!Array.isArray(users) || users.length === 0) {
        setAddAdminError("No user found with that email. They must have an existing account.");
        setAddingAdmin(false); return;
      }
      const userId = users[0].id;
      // Check not already admin
      if (adminUsers.find(a => a.user_id === userId)) {
        setAddAdminError("This user is already an admin.");
        setAddingAdmin(false); return;
      }
      // Add to platform_admins
      await fetch(SUPABASE_URL_ADMIN + "/rest/v1/platform_admins", {
        method: "POST",
        headers: { ...sbH(adminSession.access_token), "Prefer": "return=representation" },
        body: JSON.stringify({ user_id: userId, is_super: false }),
      });
      await loadAdminUsers(adminSession.access_token);
      setNewAdminEmail("");
    } catch(e) { setAddAdminError("Error: " + e.message); }
    setAddingAdmin(false);
  };

  const removeAdmin = async (userId) => {
    if (!confirm("Remove this admin?")) return;
    await fetch(SUPABASE_URL_ADMIN + "/rest/v1/platform_admins?user_id=eq." + userId, {
      method: "DELETE",
      headers: sbH(adminSession.access_token)
    });
    setAdminUsers(prev => prev.filter(a => a.user_id !== userId));
  };

  // ── Login screen ──
  if (!adminChecked) {
    return (
      <div style={{minHeight:"100vh", display:"flex", alignItems:"center", justifyContent:"center", background:"#0c0c0c"}}>
        <div style={{color:"#f0ab2e", fontSize:14}}>Loading...</div>
      </div>
    );
  }

  if (!adminSession) {
    return (
      <div style={{minHeight:"100vh", display:"flex", alignItems:"center", justifyContent:"center", background:"#0c0c0c", padding:24}}>
        <div style={{background:"#1a1a1a", borderRadius:16, padding:32, width:"100%", maxWidth:380, boxShadow:"0 8px 32px rgba(0,0,0,0.4)"}}>
          <div style={{textAlign:"center", marginBottom:28}}>
            <div style={{fontSize:28, fontWeight:800, color:"#f0ab2e", letterSpacing:"-0.5px"}}>BlacktopIQ</div>
            <div style={{fontSize:13, color:"#888", marginTop:4}}>Platform Admin</div>
          </div>
          <label style={{display:"block", fontSize:13, color:"#aaa", marginBottom:6}}>Email
            <input type="email" value={adminEmail} onChange={e => setAdminEmail(e.target.value)}
              style={{display:"block", width:"100%", marginTop:4, padding:"10px 12px", borderRadius:8, border:"1px solid #333", background:"#111", color:"#fff", fontSize:14, boxSizing:"border-box"}}
              onKeyDown={e => e.key==="Enter" && login()}/>
          </label>
          <label style={{display:"block", fontSize:13, color:"#aaa", marginBottom:16, marginTop:12}}>Password
            <input type="password" value={adminPassword} onChange={e => setAdminPassword(e.target.value)}
              style={{display:"block", width:"100%", marginTop:4, padding:"10px 12px", borderRadius:8, border:"1px solid #333", background:"#111", color:"#fff", fontSize:14, boxSizing:"border-box"}}
              onKeyDown={e => e.key==="Enter" && login()}/>
          </label>
          {loginError && <div style={{fontSize:12, color:"#ef4444", background:"rgba(239,68,68,0.1)", borderRadius:6, padding:"8px 12px", marginBottom:12}}>{loginError}</div>}
          <button onClick={login} disabled={loggingIn}
            style={{width:"100%", padding:"11px 0", borderRadius:8, border:"none", cursor:"pointer", fontSize:14, fontWeight:700,
              background: loggingIn ? "#555" : "#f0ab2e", color:"#000", opacity: loggingIn ? 0.7 : 1}}>
            {loggingIn ? "Signing in..." : "Sign In"}
          </button>
        </div>
      </div>
    );
  }

  // ── Admin dashboard ──
  return (
    <div style={{minHeight:"100vh", background:"#f5f5f5"}}>
      {/* Header */}
      <div style={{background:"#0c0c0c", padding:"12px 24px", display:"flex", alignItems:"center", justifyContent:"space-between"}}>
        <div style={{fontSize:18, fontWeight:800, color:"#f0ab2e"}}>BlacktopIQ Admin</div>
        <div style={{display:"flex", alignItems:"center", gap:12}}>
          <span style={{fontSize:12, color:"#888"}}>{adminSession.user.email}</span>
          <button onClick={logout} style={{fontSize:12, color:"#aaa", background:"transparent", border:"1px solid #333", borderRadius:6, padding:"4px 10px", cursor:"pointer"}}>Sign Out</button>
        </div>
      </div>

      {/* Content */}
      <div style={{maxWidth:1200, margin:"0 auto", padding:24}}>
        <PlatformAdminView
          setView={() => {}}
          accessToken={adminSession.access_token}
          permissions={permissions}
          setPermissions={setPermissions}
          syncPermissions={async (p) => {
            setPermissions(p);
            try {
              await fetch(SUPABASE_URL_ADMIN + "/rest/v1/global_permissions?select=id&limit=1", { headers: sbH(adminSession.access_token) });
            } catch(e) {}
          }}
        />

        {/* Admin Users Management */}
        <section style={{background:"#fff", borderRadius:12, padding:24, marginTop:20, boxShadow:"0 1px 4px rgba(0,0,0,0.08)"}}>
          <h2 style={{fontSize:18, fontWeight:700, margin:"0 0 4px"}}>Platform Admins</h2>
          <p style={{fontSize:13, color:"#888", margin:"0 0 16px"}}>Manage who has access to this dashboard.</p>

          {/* Admin list */}
          {adminUsers.map(a => (
            <div key={a.user_id} style={{display:"flex", alignItems:"center", justifyContent:"space-between", padding:"10px 0", borderBottom:"1px solid #f0f0f0"}}>
              <div>
                <div style={{fontWeight:600, fontSize:14}}>{a.name || a.email || a.user_id.slice(0,8)+"..."}</div>
                <div style={{fontSize:12, color:"#888"}}>{a.email}{a.is_super ? " · Super Admin" : ""}</div>
              </div>
              {isSuperAdmin && !a.is_super && (
                <button onClick={() => removeAdmin(a.user_id)}
                  style={{fontSize:12, color:"#ef4444", background:"#fef2f2", border:"1px solid #fecaca", borderRadius:6, padding:"4px 10px", cursor:"pointer"}}>
                  Remove
                </button>
              )}
              {a.is_super && <span style={{fontSize:11, color:"#f0ab2e", fontWeight:700}}>SUPER</span>}
            </div>
          ))}

          {/* Add admin */}
          {isSuperAdmin && (
            <div style={{marginTop:16}}>
              <div style={{fontSize:13, fontWeight:600, marginBottom:8}}>Add Admin</div>
              <p style={{fontSize:12, color:"#888", marginBottom:10}}>The user must already have a BlacktopIQ account.</p>
              <div style={{display:"flex", gap:8}}>
                <input type="email" value={newAdminEmail} onChange={e => setNewAdminEmail(e.target.value)}
                  placeholder="email@example.com"
                  style={{flex:1, padding:"8px 12px", borderRadius:8, border:"1px solid #ddd", fontSize:13}}
                  onKeyDown={e => e.key==="Enter" && addAdmin()}/>
                <button onClick={addAdmin} disabled={addingAdmin}
                  style={{padding:"8px 16px", borderRadius:8, border:"none", cursor:"pointer", fontSize:13, fontWeight:600,
                    background:"#f0ab2e", color:"#000", opacity: addingAdmin ? 0.6 : 1}}>
                  {addingAdmin ? "Adding..." : "Add"}
                </button>
              </div>
              {addAdminError && <div style={{fontSize:12, color:"#ef4444", marginTop:6}}>{addAdminError}</div>}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

function App() {
  const [view,          setViewRaw]      = useState("home");
  const [viewHistory,   setViewHistory]  = useState([]); // stack of previous views, for global Back button
  // navigateTo: use this for all "go to a new screen" navigation — pushes the
  // current view onto the history stack so the Back button can return to it.
  const navigateTo = (next) => {
    setViewHistory(h => [...h, view]);
    setViewRaw(next);
  };
  // goBack: pop the last view off the stack and go there directly (no push).
  const goBack = () => {
    setViewHistory(h => {
      if (h.length === 0) return h;
      const prev = h[h.length - 1];
      setViewRaw(prev);
      return h.slice(0, -1);
    });
  };
  const [jobs,          setJobs]         = useState([]);
  const [rates,         setRates]        = useState({...DEFAULT_RATES});
  const [currentJobId,  setCurrentJobId] = useState(null);
  const [loading,       setLoading]      = useState(true);
  const [syncStatus,    setSyncStatus]   = useState("");
  const [offlineQueue,  setOfflineQueue]  = useState(() => {
    try { return JSON.parse(localStorage.getItem("biq_offline_jobs") || "[]"); } catch(e) { return []; }
  });
  const [laborEntries,  setLaborEntries] = useState([]);
  const [zones,         setZones]        = useState(null);
  const [permissions,   setPermissions]  = useState(null);
  const [homeBase,      setHomeBase]     = useState(null); // { address, lat, lng }
  const [companySettings, setCompanySettings] = useState({
    name: "", phone: "", email: "", logoB64: "",
    legalTerms: "", depositTerms: "A 25% deposit is required to schedule work. Balance due upon completion.",
    street: "", city: "", state: "", zip: "", website: "", googleReviewUrl: "",
  });
  const [iconStyle,     setIconStyle]    = useState("emoji"); // "emoji" | "lucide" — global, admin-set
  const [offAppWorkers, setOffAppWorkers] = useState([]);
  const [reportSettings, setReportSettings] = useState({
    laborPct: 16, fuelPct: 5, cogsPct: 25, overheadPct: 15,
    ebitdaTargetPct: 20, ebitdaTargetDollars: "",
  });
  const [teamUsers,     setTeamUsers]    = useState([]);
  const [crews,         setCrews]        = useState([]);
  const [materials,         setMaterials]         = useState([]);
  const [materialSettings,  setMaterialSettings]  = useState(null);
  const [stockChecks,       setStockChecks]       = useState([]);
  const [crmLogs,           setCrmLogs]           = useState([]);
  const [customers,         setCustomers]         = useState([]);
  const [expenses,          setExpenses]          = useState([]);
  const [vendors,           setVendors]           = useState([]);
  const [currentUserName,   setCurrentUserName]   = useState("");
  const isDesktopLayout = useIsDesktop();

  // ── Auth state ──
  const [session,    setSession]    = useState(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [userRole,   setUserRole]   = useState("crew");
  const [userRoles,  setUserRoles]  = useState(["crew"]); // multi-role; userRole stays as the "primary" role for legacy single-role checks
  const [profileNeedsSetup, setProfileNeedsSetup] = useState(false);
  // ── Multi-tenancy: which companies this login belongs to, and which one
  // is currently active. A user can belong to several (tenant_users has one
  // row per membership); we default to the first one found. The actual
  // per-tenant role (set in tenant_users) takes over from the old single
  // profiles.role/roles the moment a tenant is resolved — see fetchTenants.
  const [myTenants,      setMyTenants]      = useState([]); // [{tenantId, role, companyName, data}]
  const [currentTenantId, setCurrentTenantId] = useState(null);

  const [isPlatformAdmin, setIsPlatformAdmin] = useState(false);
  const fetchIsPlatformAdmin = async (accessToken) => {
    try {
      const res = await fetch("/api/admin?action=check-platform-admin", {
        headers: { "Authorization": "Bearer " + accessToken },
      });
      const data = await res.json();
      setIsPlatformAdmin(!!data?.isPlatformAdmin);
    } catch(e) { setIsPlatformAdmin(false); }
  };

  const fetchTenants = async (userId, accessToken) => {
    try {
      const tuRes = await sbFetch("tenant_users?user_id=eq."+userId+"&status=eq.active&select=tenant_id,role", {}, accessToken);
      const tuData = await tuRes.json();
      if (!Array.isArray(tuData) || tuData.length === 0) { setMyTenants([]); return; }
      const ids = tuData.map(t => t.tenant_id);
      const tRes = await sbFetch("tenants?id=in.("+ids.join(",")+")&select=id,data", {}, accessToken);
      const tData = await tRes.json();
      const merged = tuData.map(tu => {
        const t = (tData||[]).find(x => x.id === tu.tenant_id);
        return { tenantId: tu.tenant_id, role: tu.role, companyName: t?.data?.companyName || "Unknown Company", data: t?.data || {} };
      });
      setMyTenants(merged);
      setCurrentTenantId(prev => {
        // Keep the current pick if it's still valid (e.g. on a profile
        // refresh); otherwise default to the first membership found.
        if (prev && merged.some(m => m.tenantId === prev)) return prev;
        return merged[0]?.tenantId || null;
      });
    } catch(e) { console.error("fetchTenants error:", e); }
  };

  // tFetch: the tenant-aware, auth-aware replacement for sbFetch. Always
  // sends the logged-in user's own access token (not the shared anon key),
  // and for every tenant-scoped table automatically:
  //   - GET:            adds &tenant_id=eq.<current> so reads never see
  //                      another company's rows
  //   - POST/PATCH:      stamps tenant_id onto whatever's being written, so
  //                      new/updated rows always belong to the right company
  //   - DELETE:          adds &tenant_id=eq.<current> too, as a second guard
  //                      against deleting a row that isn't actually yours
  // Tables outside TENANT_SCOPED_TABLES (profiles, tenants, tenant_users,
  // tenant_invites) pass through untouched — those are either global or are
  // how a tenant gets resolved in the first place.
  // NOTE: this scoping is enforced here in application code, NOT yet by RLS
  // (RLS tightening is the deliberately-last step of the multi-tenancy plan,
  // only once everything using tFetch is proven correct).
  const tFetch = (path, opts={}) => {
    const accessToken = session?.access_token;
    const tableName = path.split("?")[0];
    if (!TENANT_SCOPED_TABLES.includes(tableName) || !currentTenantId) {
      return sbFetch(path, opts, accessToken);
    }
    const method = (opts.method || "GET").toUpperCase();
    let finalPath = path;
    let finalOpts = opts;
    if (method === "GET" || method === "DELETE") {
      const sep = path.includes("?") ? "&" : "?";
      finalPath = path + sep + "tenant_id=eq." + currentTenantId;
    } else if (method === "POST" || method === "PATCH") {
      try {
        const bodyObj = JSON.parse(opts.body || "{}");
        if (Array.isArray(bodyObj)) {
          bodyObj.forEach(o => { o.tenant_id = currentTenantId; });
        } else {
          bodyObj.tenant_id = currentTenantId;
        }
        finalOpts = {...opts, body: JSON.stringify(bodyObj)};
      } catch(e) { /* body wasn't JSON — leave it untouched */ }
    }
    return sbFetch(finalPath, finalOpts, accessToken);
  };

  // Switching companies just changes which one tFetch scopes everything to —
  // the main data-load effect re-fires automatically since it depends on
  // currentTenantId. Deliberately NOT touching userRole/userRoles here: that
  // system is global (profiles.roles) and predates per-tenant membership
  // roles (tenant_users.role, which is a single value, not an array) — unifying
  // those is a real decision to make later, not something to collapse
  // silently while just building the switcher.
  const switchTenant = (tenantId) => {
    if (tenantId === currentTenantId) return;
    setCurrentTenantId(tenantId);
  };

  const fetchProfile = async (userId, accessToken) => {
    try {
      const res = await sbFetch("profiles?id=eq."+userId+"&select=role,roles,first_name,last_name,phone", {}, accessToken);
      const data = await res.json();
      if (Array.isArray(data) && data[0]) {
        const profile = data[0];
        if (profile.role) setUserRole(profile.role);
        setUserRoles(Array.isArray(profile.roles) && profile.roles.length ? profile.roles : (profile.role ? [profile.role] : ["crew"]));
        const fullName = [profile.first_name, profile.last_name].filter(Boolean).join(" ");
        if (fullName) setCurrentUserName(fullName);
        // Owners get their own company setup flow — only gate
        // estimator/crew/crewlead/manager on the basic profile wizard.
        const isOwner = profile.role === "owner";
        const missingRequired = !profile.first_name?.trim() || !profile.last_name?.trim() || !profile.phone?.trim();
        setProfileNeedsSetup(!isOwner && missingRequired);
      }
    } catch(e) { console.error("fetchProfile error:", e); }
  };

  // ── Detect Supabase invite/recovery link in the URL hash ──
  const [inviteToken, setInviteToken] = useState(null); // access_token from #...&type=invite|recovery
  // ── Detect a "create a new company" join link — a different mechanism
  // entirely from the above: that one is Supabase inviting an existing-style
  // user by email; this one is a custom token (tenant_invites) for someone
  // who doesn't have an account yet and is about to create a whole new company. ──
  const [joinToken,        setJoinToken]        = useState(null);
  const [showPublicSignup, setShowPublicSignup] = useState(false);
  const [signupToken,      setSignupToken]      = useState(null);
  const [requestTenantId,  setRequestTenantId]  = useState(() => new URLSearchParams(window.location.search).get("request") || null);

  // ── Restore session on mount ──
  useEffect(() => {
    const joinParam    = new URLSearchParams(window.location.search).get("join");
    const requestParam   = new URLSearchParams(window.location.search).get("request");
    const subscribedParam = new URLSearchParams(window.location.search).get("subscribed");
    const signupParam  = new URLSearchParams(window.location.search).get("signup");
    if (signupParam) {
      setShowPublicSignup(true);
      setAuthChecked(true);
      window.history.replaceState(null, "", window.location.pathname);
      return;
    }
    if (subscribedParam) {
      window.history.replaceState(null, "", window.location.pathname);
      // Will show success banner once app loads — store in sessionStorage
      sessionStorage.setItem("justSubscribed", "1");
    }
    if (requestParam) {
      setRequestTenantId(requestParam);
      setAuthChecked(true);
      window.history.replaceState(null, "", window.location.pathname);
      return;
    }
    if (joinParam) {
      setJoinToken(joinParam);
      setAuthChecked(true);
      window.history.replaceState(null, "", window.location.pathname);
      return;
    }

    // New Supabase format: token_hash + type as query params (used by auth hooks)
    // e.g. /?token_hash=abc123&type=recovery
    const qp = new URLSearchParams(window.location.search);
    const tokenHash = qp.get("token_hash");
    const tokenType = qp.get("type");
    if (tokenHash && tokenType) {
      window.history.replaceState(null, "", window.location.pathname);
      // Exchange token_hash for a real session via Supabase OTP verify endpoint
      const verifyAndSet = async () => {
        try {
          const res = await fetch(SUPABASE_URL + "/auth/v1/verify", {
            method: "POST",
            headers: {
              "apikey": SUPABASE_KEY,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({ token_hash: tokenHash, type: tokenType }),
          });
          const data = await res.json();
          if (data?.access_token) {
            // For recovery/invite — show the set password screen
            setInviteToken(data.access_token);
          } else {
            console.error("token_hash verify failed:", data);
          }
        } catch(e) {
          console.error("token_hash verify error:", e);
        }
        setAuthChecked(true);
      };
      verifyAndSet();
      return;
    }

    // Legacy Supabase format: access_token in URL hash
    // e.g. /#access_token=...&type=invite
    const hash = window.location.hash || "";
    if (hash.includes("access_token") && (hash.includes("type=invite") || hash.includes("type=recovery") || hash.includes("type=signup"))) {
      const params = new URLSearchParams(hash.slice(1));
      const token = params.get("access_token");
      const type  = params.get("type");
      if (token) {
        if (type === "signup") {
          setSignupToken(token);
        } else {
          setInviteToken(token);
        }
        setAuthChecked(true);
        window.history.replaceState(null, "", window.location.pathname);
        return;
      }
    }

    const restore = async () => {
      const saved = loadSession();
      if (!saved) { setAuthChecked(true); return; }
      const expiresAt = saved.expires_at ? saved.expires_at * 1000 : 0;
      const isExpired = Date.now() > expiresAt - 60000; // refresh if within 1 min of expiry
      if (isExpired && saved.refresh_token) {
        try {
          const fresh = await authRefresh(saved.refresh_token);
          saveSession(fresh);
          setSession(fresh);
          await fetchProfile(fresh.user.id, fresh.access_token);
          await fetchTenants(fresh.user.id, fresh.access_token);
          await fetchIsPlatformAdmin(fresh.access_token);
        } catch(e) {
          clearSession();
        }
      } else {
        setSession(saved);
        await fetchProfile(saved.user.id, saved.access_token);
        await fetchTenants(saved.user.id, saved.access_token);
        await fetchIsPlatformAdmin(saved.access_token);
      }
      setAuthChecked(true);
    };
    restore();
  }, []);

  const handleInvitePasswordSet = async (newSession) => {
    setInviteToken(null);
    saveSession(newSession);
    setSession(newSession);
    await fetchProfile(newSession.user.id, newSession.access_token);
    await fetchTenants(newSession.user.id, newSession.access_token);
    await fetchIsPlatformAdmin(newSession.access_token);
  };

  const handleSignupComplete = async (newSession) => {
    setSignupToken(null);
    saveSession(newSession);
    setSession(newSession);
    await fetchProfile(newSession.user.id, newSession.access_token);
    await fetchTenants(newSession.user.id, newSession.access_token);
    await fetchIsPlatformAdmin(newSession.access_token);
  };

  const handleLoginSuccess = async (newSession) => {
    setSession(newSession);
    await fetchProfile(newSession.user.id, newSession.access_token);
    await fetchTenants(newSession.user.id, newSession.access_token);
    await fetchIsPlatformAdmin(newSession.access_token);
  };

  // After redeem-tenant-invite creates the account + company server-side,
  // this just signs them in for real and clears the join flow.
  const handleJoinSuccess = async (newSession) => {
    setJoinToken(null);
    saveSession(newSession);
    setSession(newSession);
    await fetchProfile(newSession.user.id, newSession.access_token);
    await fetchTenants(newSession.user.id, newSession.access_token);
    await fetchIsPlatformAdmin(newSession.access_token);
  };

  // If the active view isn't allowed for this role, fall back to jobs.
  // "export", "permissions", "team" stay admin-only regardless of the configurable matrix.
  useEffect(() => {
    const isOwner = userRole === "owner" || (userRoles||[]).includes("owner");
    const isManager = isOwner || userRole === "manager" || (userRoles||[]).includes("manager");
    const alwaysOwnerOnly = ["export","permissions","owner-hub","homebase","company-settings","referral","request-form"];
    if (alwaysOwnerOnly.includes(view) && !isOwner) { setViewRaw("jobs"); return; }
    if (view === "team" && !isManager) { setViewRaw("jobs"); return; }
    if (ALL_TABS.some(t => t.key === view)) {
      const level = getAccessLevel(permissions, view, userRoles||userRole);
      if (level === "hidden" && !isOwner) setViewRaw("jobs");
    }
  }, [userRole, userRoles, view, permissions]);

  const handleLogout = () => {
    clearSession();
    setSession(null);
    setUserRole("crew");
    setUserRoles(["crew"]);
    setViewHistory([]);
    setMyTenants([]);
    setCurrentTenantId(null);
    setIsPlatformAdmin(false);
  };

  // ── Load all data — waits for currentTenantId to resolve (so the very
  // first load is correctly scoped, not fired before the tenant is known),
  // and re-fires whenever it changes — i.e. switching companies reloads
  // everything for the newly-selected one. ──
  useEffect(() => {
    if (!currentTenantId) return; // still resolving which company this login belongs to
    setLoading(true);
    const load = async () => {
      try {
        const jr = await tFetch("jobs?select=id,data&order=id.desc");
        const jd = await jr.json();
        if (Array.isArray(jd)) setJobs(jd.map(row => ({areas:[], ...row.data, id: row.id})));

        const rr = await tFetch("rates?select=data&order=id.desc&limit=1");
        const rd = await rr.json();
        if (Array.isArray(rd) && rd.length > 0) setRates(rd[0].data);

        const lr = await tFetch("labor?select=id,data&order=id.desc");
        const ld = await lr.json();
        if (Array.isArray(ld)) setLaborEntries(ld.map(row => ({...row.data, id: row.id})));

        const er = await tFetch("expenses?select=id,data&order=id.desc");
        const ed = await er.json();
        if (Array.isArray(ed)) setExpenses(ed.map(row => ({...row.data, id: row.id})));

        const vr = await tFetch("vendors?select=id,data&order=id.desc");
        const vd = await vr.json();
        if (Array.isArray(vd)) setVendors(vd.map(row => ({...row.data, id: row.id})));

        const zr = await tFetch("zones?select=data&limit=1");
        const zd = await zr.json();
        if (Array.isArray(zd) && zd.length > 0) setZones(zd[0].data);

        const pr = await sbFetch("permissions?select=data&limit=1", {}, session?.access_token);
        const pd = await pr.json();
        if (Array.isArray(pd) && pd.length > 0) setPermissions(pd[0].data);

        try {
          const tr = await fetch("/api/admin?action=list-users&tenantId=" + currentTenantId);
          const td = await tr.json();
          if (tr.ok && Array.isArray(td.users)) setTeamUsers(td.users);
        } catch(e) { console.error("load team users error:", e); }

        const cr = await tFetch("crews?select=id,data&order=id.asc");
        const cd = await cr.json();
        if (Array.isArray(cd)) setCrews(cd.map(row => ({...row.data, id: row.id})));

        const hr = await tFetch("homebase?select=data&order=id.desc&limit=1");
        const hd = await hr.json();
        if (Array.isArray(hd) && hd.length > 0) setHomeBase(hd[0].data);

        try {
          const csr = await tFetch("company_settings?select=data&order=id.desc&limit=1");
          const csd = await csr.json();
          if (Array.isArray(csd) && csd.length > 0 && csd[0].data && csd[0].data.name) {
            setCompanySettings(prev => ({...prev, ...csd[0].data}));
          }
        } catch(e) { console.error("load company_settings error:", e); }

        const sr = await tFetch("appsettings?select=data&order=id.desc&limit=1");
        const sd = await sr.json();
        if (Array.isArray(sd) && sd.length > 0) {
          if (sd[0].data?.iconStyle) setIconStyle(sd[0].data.iconStyle);
          if (sd[0].data?.reportSettings) setReportSettings(prev => ({...prev, ...sd[0].data.reportSettings}));
          if (sd[0].data?.offAppWorkers) setOffAppWorkers(sd[0].data.offAppWorkers);
        }

        const mr = await tFetch("materials?select=id,data&order=id.desc");
        const md = await mr.json();
        if (Array.isArray(md)) setMaterials(md.map(row => ({...row.data, id: row.id})));

        const msr = await tFetch("materialsettings?select=data&order=id.desc&limit=1");
        const msd = await msr.json();
        if (Array.isArray(msd) && msd.length > 0) setMaterialSettings(msd[0].data);

        const scr = await tFetch("materialstock?select=id,data&order=id.desc");
        const scd = await scr.json();
        if (Array.isArray(scd)) setStockChecks(scd.map(row => ({...row.data, id: row.id})));

        const clr = await tFetch("crmlogs?select=id,data&order=id.desc");
        const cld = await clr.json();
        if (Array.isArray(cld)) setCrmLogs(cld.map(row => ({...row.data, id: row.id})));

        const cur = await tFetch("customers?select=id,data&order=id.desc");
        const cud = await cur.json();
        if (Array.isArray(cud)) setCustomers(cud.map(row => ({...row.data, id: row.id})));
      } catch(e) {
        console.error("Load error:", e);
        setSyncStatus("⚠️ Could not connect to database");
      }
      setLoading(false);
    };
    load();
  }, [currentTenantId]);

  // Jobs commonly get updated from a different login entirely — an admin
  // assigning an estimate, a crew lead marking something completed — and
  // this app has no live/realtime sync between sessions, only a one-time
  // fetch on load. Two complementary fixes for that, short of building full
  // realtime: refetch whenever the tab regains focus (covers "switched away
  // and back"), and poll every 5 minutes while the tab is actually visible.
  // A 2-minute debounce prevents hammering the DB if the user rapidly
  // switches tabs — egress saver.
  useEffect(() => {
    if (!currentTenantId) return;
    let inFlight = false;
    let lastFetch = Date.now();
    const POLL_INTERVAL = 5 * 60 * 1000;   // 5 minutes
    const MIN_REFETCH_GAP = 2 * 60 * 1000; // 2 minutes between focus-triggered refetches
    const refetchJobs = async (force = false) => {
      if (inFlight) return;
      if (!force && Date.now() - lastFetch < MIN_REFETCH_GAP) return;
      inFlight = true;
      try {
        const jr = await tFetch("jobs?select=id,data&order=id.desc");
        const jd = await jr.json();
        if (Array.isArray(jd)) {
          const pending = pendingSyncRef.current || {};
          setJobs(jd.map(row => pending[row.id] || {...row.data, id: row.id}));
        }
        lastFetch = Date.now();
      } catch(e) { console.error("Refetch jobs error:", e); }
      inFlight = false;
    };
    const onFocus = () => refetchJobs();
    const onVisible = () => { if (document.visibilityState === "visible") refetchJobs(); };
    window.addEventListener("focus", onFocus);
    document.addEventListener("visibilitychange", onVisible);
    const pollId = setInterval(() => { if (document.visibilityState === "visible") refetchJobs(true); }, POLL_INTERVAL);
    return () => {
      window.removeEventListener("focus", onFocus);
      document.removeEventListener("visibilitychange", onVisible);
      clearInterval(pollId);
    };
  }, [currentTenantId]);

  const syncZones = async (zonesData) => {
    try {
      await tFetch("zones?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ data: zonesData }),
      });
    } catch(e) { console.error("syncZones error:", e); }
  };

  const syncPermissions = async (permissionsData) => {
    try {
      await sbFetch("permissions?id=eq.1", {
        method: "PATCH",
        headers: { "Prefer": "return=minimal" },
        body: JSON.stringify({ data: permissionsData }),
      }, session?.access_token);
      setPermissions(permissionsData);
    } catch(e) { console.error("syncPermissions error:", e); }
  };

  const syncHomeBase = async (homeBaseData) => {
    try {
      await tFetch("homebase?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ data: homeBaseData }),
      });
    } catch(e) { console.error("syncHomeBase error:", e); }
  };

  const syncCompanySettings = async (csData) => {
    try {
      setCompanySettings(prev => ({...prev, ...csData}));
      await tFetch("company_settings?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates,return=minimal" },
        body: JSON.stringify({ data: csData }),
      });
      // Keep tenant.data.logoUrl in sync so the nav bar always reflects
      // the current logo even if the original wizard value was a file path
      if (csData.logoB64) {
        const curTenant = myTenants.find(t => t.tenantId === currentTenantId);
        if (curTenant) {
          const updatedData = { ...curTenant.data, logoUrl: "data:image/png;base64," + csData.logoB64 };
          await tFetch("tenants?id=eq." + curTenant.tenantId, {
            method: "PATCH",
            body: JSON.stringify({ data: updatedData }),
          });
          setMyTenants(prev => prev.map(t => t.tenantId === currentTenantId ? { ...t, data: updatedData } : t));
        }
      }
    } catch(e) { console.error("syncCompanySettings error:", e); }
  };

  // Single writer for appsettings — always merges all keys so no field overwrites another
  const syncAppSettings = async (patch) => {
    try {
      // Fetch current data first so we can merge
      const r = await tFetch("appsettings?select=data&order=id.desc&limit=1");
      const rows = await r.json();
      const current = (Array.isArray(rows) && rows[0]?.data) || {};
      await tFetch("appsettings?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ data: { ...current, ...patch } }),
      });
    } catch(e) { console.error("syncAppSettings error:", e); }
  };

  const syncIconStyle = async (style) => {
    setIconStyle(style);
    await syncAppSettings({ iconStyle: style });
  };

  const syncOffAppWorkers = async (workers) => {
    setOffAppWorkers(workers);
    await syncAppSettings({ offAppWorkers: workers });
  };

  const syncReportSettings = async (settings) => {
    setReportSettings(settings);
    await syncAppSettings({ reportSettings: settings });
  };

  // Assign a newly created/edited job to its nearest existing zone centroid
  // (lightweight live update — does not recalculate centroids themselves)
  const assignJobToNearestZone = async (job) => {
    if (!zones?.list?.length) return;

    // If this job's status isn't one of the categories the zones were built for,
    // make sure it isn't sitting in a zone/overflow list, and stop — no geocoding needed.
    if (zones.filterStatuses && !zones.filterStatuses.includes(job.status)) {
      const stillPresent = zones.list.some(z => z.jobIds.includes(job.id)) || (zones.overflow?.jobIds||[]).includes(job.id);
      if (!stillPresent) return;
      const cleared = {...zones};
      cleared.list = zones.list.map(z => ({
        ...z,
        jobIds: z.jobIds.filter(id => id !== job.id),
        jobCount: z.jobIds.filter(id => id !== job.id).length,
      }));
      cleared.overflow = {...cleared.overflow, jobIds: (cleared.overflow?.jobIds||[]).filter(id => id !== job.id)};
      cleared.overflow.count = cleared.overflow.jobIds.length;
      setZones(cleared);
      syncZones(cleared);
      return;
    }

    // Already geocoded — reuse it. Trust legacy records with no geoAddr yet;
    // only force a re-geocode when geoAddr is present and no longer matches,
    // or the cached coordinates are implausibly far from home base.
    const addrStr = fullAddressOf(job);
    if (!addrStr) return;
    // A bare state alone isn't specific enough to geocode reliably — skip rather
    // than risk plotting the job in the wrong country (e.g. "PA" → Panama).
    if (!hasSufficientAddress(job)) return;
    const cached = job.geoLat && job.geoLng && (!job.geoAddr || job.geoAddr === addrStr)
      && !isImplausibleLocation({lat: job.geoLat, lng: job.geoLng}, homeBase);
    const geo = cached ? { lat: job.geoLat, lng: job.geoLng } : await geocodeAddress(geocodeQueryOf(job), homeBase);
    if (!geo) return;
    if (!cached) {
      try {
        await tFetch("jobs?id=eq."+job.id, {
          method: "PATCH",
          body: JSON.stringify({ data: {...job, geoLat: geo.lat, geoLng: geo.lng, geoAddr: addrStr} }),
        });
      } catch(e) {}
      setJobs(prev => prev.map(jj => jj.id === job.id ? {...jj, geoLat: geo.lat, geoLng: geo.lng, geoAddr: addrStr} : jj));
    }

    let bestIdx = -1, bestDist = Infinity;
    zones.list.forEach((z, i) => {
      const d = haversine(geo, z.centroid);
      if (d < bestDist) { bestDist = d; bestIdx = i; }
    });

    const updatedZones = {...zones};
    const isOverflow = bestDist > 25;
    updatedZones.list = zones.list.map((z, i) => ({
      ...z,
      jobIds: z.jobIds.filter(id => id !== job.id).concat(i===bestIdx && !isOverflow ? [job.id] : []),
      jobCount: z.jobIds.filter(id => id !== job.id).concat(i===bestIdx && !isOverflow ? [job.id] : []).length,
    }));
    updatedZones.overflow = {
      ...updatedZones.overflow,
      jobIds: (updatedZones.overflow?.jobIds||[]).filter(id => id !== job.id).concat(isOverflow ? [job.id] : []),
    };
    updatedZones.overflow.count = updatedZones.overflow.jobIds.length;

    setZones(updatedZones);
    syncZones(updatedZones);
  };

  const syncLaborEntry = async (entry) => {
    try {
      await tFetch("labor", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncLaborEntry error:", e); }
  };

  const deleteLaborEntry = async (id) => {
    setLaborEntries(prev => prev.filter(e => e.id !== id));
    try { await tFetch("labor?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  const addLaborEntry = (entry) => {
    setLaborEntries(prev => [entry, ...prev]);
    syncLaborEntry(entry);
  };

  // ── Expenses ──
  const syncExpense = async (entry) => {
    try {
      await tFetch("expenses", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncExpense error:", e); }
  };
  const addExpense = (entry) => {
    setExpenses(prev => [entry, ...prev]);
    syncExpense(entry);
  };
  const updateExpense = (id, patch) => {
    setExpenses(prev => prev.map(e => e.id === id ? {...e, ...patch} : e));
    const updated = expenses.find(e => e.id === id);
    if (updated) syncExpense({...updated, ...patch});
  };
  const deleteExpense = async (id) => {
    setExpenses(prev => prev.filter(e => e.id !== id));
    try { await tFetch("expenses?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  // ── Vendors ──
  const syncVendor = async (v) => {
    try {
      await tFetch("vendors", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: v.id, data: v }),
      });
    } catch(e) { console.error("syncVendor error:", e); }
  };
  const addVendor = (v) => {
    setVendors(prev => [v, ...prev]);
    syncVendor(v);
  };
  const deleteVendor = async (id) => {
    setVendors(prev => prev.filter(v => v.id !== id));
    try { await tFetch("vendors?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  // ── Material purchases (Materials tab) ──
  const syncMaterial = async (entry) => {
    try {
      await tFetch("materials", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncMaterial error:", e); }
  };

  const addMaterial = (entry) => {
    setMaterials(prev => [entry, ...prev]);
    syncMaterial(entry);
  };

  const deleteMaterial = async (id) => {
    setMaterials(prev => prev.filter(m => m.id !== id));
    try { await tFetch("materials?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  const syncMaterialSettings = async (settingsData) => {
    try {
      await tFetch("materialsettings?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ data: settingsData }),
      });
    } catch(e) { console.error("syncMaterialSettings error:", e); }
  };

  // ── Material stock checks (physical on-hand readings) ──
  const syncStockCheck = async (entry) => {
    try {
      await tFetch("materialstock", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncStockCheck error:", e); }
  };

  const addStockCheck = (entry) => {
    setStockChecks(prev => [entry, ...prev]);
    syncStockCheck(entry);
  };

  const deleteStockCheck = async (id) => {
    setStockChecks(prev => prev.filter(c => c.id !== id));
    try { await tFetch("materialstock?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  // ── CRM notes / call logs ──
  const syncCrmLog = async (entry) => {
    try {
      await tFetch("crmlogs", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncCrmLog error:", e); }
  };

  const addCrmLog = (entry) => {
    setCrmLogs(prev => [entry, ...prev]);
    syncCrmLog(entry);
  };

  const deleteCrmLog = async (id) => {
    setCrmLogs(prev => prev.filter(l => l.id !== id));
    try { await tFetch("crmlogs?id=eq."+id, { method: "DELETE" }); } catch(e) {}
  };

  // ── Customers (CRM) ──
  const syncCustomer = async (entry) => {
    try {
      await tFetch("customers", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: entry.id, data: entry }),
      });
    } catch(e) { console.error("syncCustomer error:", e); }
  };

  const addCustomer = (entry) => {
    setCustomers(prev => [entry, ...prev]);
    syncCustomer(entry);
  };

  const updateCustomer = (id, fields) => {
    setCustomers(prev => prev.map(c => {
      if (c.id !== id) return c;
      const updated = {...c, ...fields};
      syncCustomer(updated);
      return updated;
    }));
  };

  // ── Upsert a single job ──
  const lastZonedAddressRef = useRef({});

  const syncJob = async (job, isRetry=false) => {
    // Don't attempt a sync until we actually know which tenant this is —
    // firing early would either silently write with no tenant_id (if
    // tFetch falls through to unscoped sbFetch) or just fail outright.
    if (!currentTenantId) {
      setTimeout(() => syncJob(job, isRetry), 300);
      return;
    }
    setSyncStatus("Saving...");
    try {
      const res = await tFetch("jobs", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ id: job.id, data: job }),
      });
      if (!res.ok) throw new Error(await res.text());
      setSyncStatus("✓ Saved");
      setTimeout(() => setSyncStatus(""), 2000);

      // Live zone re-assignment — only re-geocode/re-assign if the address actually changed
      const addrStr = fullAddressOf(job);
      if (addrStr && zones?.list?.length && lastZonedAddressRef.current[job.id] !== addrStr) {
        lastZonedAddressRef.current[job.id] = addrStr;
        assignJobToNearestZone(job);
      }
    } catch(e) {
      console.error("syncJob error:", e);
      if (!isRetry) {
        setTimeout(() => syncJob(job, true), 1000);
      } else {
        // Queue for retry when back online
        setSyncStatus("⚠️ Saved offline");
        setOfflineQueue(prev => {
          const next = [...prev.filter(j => j.id !== job.id), job];
          try { localStorage.setItem("biq_offline_jobs", JSON.stringify(next)); } catch(e) {}
          return next;
        });
      }
    }
  };

  // Flush offline queue when connectivity returns
  const flushOfflineQueue = async () => {
    const queue = (() => { try { return JSON.parse(localStorage.getItem("biq_offline_jobs") || "[]"); } catch(e) { return []; } })();
    if (!queue.length) return;
    setSyncStatus("Syncing offline changes...");
    let remaining = [...queue];
    for (const job of queue) {
      try {
        const res = await tFetch("jobs", {
          method: "POST",
          headers: { "Prefer": "resolution=merge-duplicates" },
          body: JSON.stringify({ id: job.id, data: job }),
        });
        if (res.ok) remaining = remaining.filter(j => j.id !== job.id);
      } catch(e) { /* keep in queue */ }
    }
    try { localStorage.setItem("biq_offline_jobs", JSON.stringify(remaining)); } catch(e) {}
    setOfflineQueue(remaining);
    setSyncStatus(remaining.length === 0 ? "✓ All changes synced" : `⚠️ ${remaining.length} changes still pending`);
    setTimeout(() => setSyncStatus(""), 3000);
  };

  // Auto-flush when coming back online
  useEffect(() => {
    const handler = () => { if (offlineQueue.length > 0) flushOfflineQueue(); };
    window.addEventListener("online", handler);
    return () => window.removeEventListener("online", handler);
  }, [offlineQueue]);

  // ── Upsert rates ──
  const syncRates = async (r) => {
    setSyncStatus("Saving...");
    try {
      const res = await tFetch("rates?on_conflict=tenant_id", {
        method: "POST",
        headers: { "Prefer": "resolution=merge-duplicates" },
        body: JSON.stringify({ data: r }),
      });
      if (!res.ok) throw new Error(await res.text());
      setSyncStatus("✓ Saved");
      setTimeout(() => setSyncStatus(""), 2000);
    } catch(e) {
      console.error("syncRates error:", e);
      setSyncStatus("⚠️ Save failed");
    }
  };

  // ── Delete a job ──
  const deleteJob = async (id) => {
    setJobs(prev => prev.filter(j => j.id !== id));
    try {
      await tFetch("jobs?id=eq." + id, { method: "DELETE" });
    } catch(e) { console.error("deleteJob error:", e); }
  };

  const currentJob = jobs.find(j => j.id === currentJobId) || null;

  // Keep a ref of pending syncs so debounce always uses latest state
  const pendingSyncRef = useRef({});
  const syncTimerRef   = useRef({});

  // Stamps statusChangedAt whenever fn() actually changes a job's status —
  // this is the only place that needs to know, since every status change in
  // the app (drag-and-drop, dropdowns, workflow buttons) goes through one of
  // these two functions. Powers the aging report: without this, there'd be
  // no way to know how long a job has actually been sitting at its current
  // stage, only when it was originally created.
  const withStatusStamp = (job, fn) => {
    const result = fn(job);
    if (result.status !== job.status) result.statusChangedAt = new Date().toISOString();
    return result;
  };

  // ── Audit log helper ───────────────────────────────────────────────────────
  const appendAuditLog = (job, entry) => {
    const log = Array.isArray(job.auditLog) ? job.auditLog : [];
    return { ...job, auditLog: [...log, { ...entry, timestamp: new Date().toISOString(), userId: session?.user?.id || "", userName: currentUserName || "Unknown" }] };
  };

  // Detect key changes for audit log
  const auditDiff = (prev, next) => {
    const entries = [];
    // Status change
    if (prev.status !== next.status) {
      entries.push({ action: "status_change", detail: `${prev.status} → ${next.status}` });
    }
    // Line items added
    const prevAreaIds = new Set((prev.areas||[]).map(a => a.id));
    (next.areas||[]).forEach(a => {
      if (!prevAreaIds.has(a.id)) entries.push({ action: "line_item_added", detail: `${a.name||"Area"}: ${a.serviceType} ${a.measurement||0} sq ft` });
    });
    // Line items removed
    const nextAreaIds = new Set((next.areas||[]).map(a => a.id));
    (prev.areas||[]).forEach(a => {
      if (!nextAreaIds.has(a.id)) entries.push({ action: "line_item_removed", detail: `${a.name||"Area"}: ${a.serviceType}` });
    });
    // Price override
    if (prev.totalOverride !== next.totalOverride && next.totalOverride) {
      entries.push({ action: "price_override", detail: `Override set to $${next.totalOverride}` });
    }
    // Markup/discount
    if (prev.markup !== next.markup && next.markup) entries.push({ action: "markup_changed", detail: `Markup set to ${next.markup}%` });
    if (prev.discount !== next.discount && next.discount) entries.push({ action: "discount_changed", detail: `Discount set to ${next.discount}%` });
    return entries;
  };

  const updateJob = fn => {
    setJobs(prev => {
      const next = prev.map(j => {
        if (j.id !== currentJobId) return j;
        const updated = withStatusStamp(j, fn);
        // Append audit entries for key changes
        const diffs = auditDiff(j, updated);
        return diffs.length > 0 ? diffs.reduce((acc, entry) => appendAuditLog(acc, entry), updated) : updated;
      });
      // Find updated job and schedule debounced sync
      const updated = next.find(j => j.id === currentJobId);
      if (updated) {
        pendingSyncRef.current[updated.id] = updated;
        clearTimeout(syncTimerRef.current[updated.id]);
        syncTimerRef.current[updated.id] = setTimeout(() => {
          const toSync = pendingSyncRef.current[updated.id];
          if (toSync) syncJob(toSync);
          delete pendingSyncRef.current[updated.id];
        }, 800);
      }
      return next;
    });
  };

  // Update any job by ID (used for scheduling, status changes, etc.)
  const updateJobById = (id, fn) => {
    setJobs(prev => {
      const next = prev.map(j => j.id===id ? withStatusStamp(j, fn) : j);
      const updated = next.find(j => j.id===id);
      if (updated) {
        pendingSyncRef.current[updated.id] = updated;
        clearTimeout(syncTimerRef.current[updated.id]);
        syncTimerRef.current[updated.id] = setTimeout(() => {
          const toSync = pendingSyncRef.current[updated.id];
          if (toSync) syncJob(toSync);
          delete pendingSyncRef.current[updated.id];
        }, 800);
      }
      return next;
    });
  };

  const setCurrentJob = job => setCurrentJobId(job ? job.id : null);

  const handleSetRates = (r) => { setRates(r); syncRates(r); };

  const handleSetJobs = (fnOrArr) => {
    // Used by the Jobs pipeline for create/delete
    setJobs(prev => {
      const next = typeof fnOrArr === "function" ? fnOrArr(prev) : fnOrArr;
      // Detect new job (added to front)
      if (next.length > prev.length) {
        const newJob = next[0];
        tFetch("jobs", {
          method: "POST",
          headers: { "Prefer": "resolution=merge-duplicates" },
          body: JSON.stringify({ id: newJob.id, data: newJob }),
        });
      }
      return next;
    });
  };

  // Public routes — render before any auth check
  if (requestTenantId) return <EstimateRequestForm tenantId={requestTenantId}/>;

  if (!authChecked) return (
    <div style={{...S.app, alignItems:"center", justifyContent:"center"}}>
      <div style={{textAlign:"center", padding:"0 40px"}}>
        <img
          src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64}
          alt="BlacktopIQ"
          style={{width:"100%", maxWidth: isDesktopLayout ? 560 : 420, display:"block", margin:"0 auto"}}
        />
      </div>
    </div>
  );

  if (inviteToken) return <SetPasswordView inviteToken={inviteToken} onSuccess={handleInvitePasswordSet}/>;
  if (requestTenantId) return <EstimateRequestForm tenantId={requestTenantId}/>;
  if (joinToken) return <JoinCompanyView token={joinToken} onSuccess={handleJoinSuccess}/>;

  if (signupToken) return <CompleteSignupView accessToken={signupToken} onSuccess={handleSignupComplete}/>;
  if (showPublicSignup && !session) return <PublicSignupView onBack={() => setShowPublicSignup(false)}/>;
  if (!session) return <LoginView onSuccess={handleLoginSuccess} onShowSignup={() => setShowPublicSignup(true)}/>;

  if (profileNeedsSetup) return (
    <ProfileSetupWizard
      accessToken={session.access_token}
      userId={session.user?.id}
      onComplete={() => setProfileNeedsSetup(false)}
    />
  );

  // Only a brand-new tenant (created via the join flow, which explicitly
  // sets setupComplete:false) triggers this — an absent field (e.g. TPS's
  // own pre-existing tenant row, migrated without this field at all) does
  // NOT trigger it. That distinction matters: falsy-but-absent should mean
  // "this predates the wizard, leave it alone," not "show the wizard."
  const currentTenant = myTenants.find(t => t.tenantId === currentTenantId);
  if (userRole === "owner" && currentTenant && currentTenant.data?.setupComplete === false) {
    return (
      <CompanySetupWizard
        tenant={currentTenant}
        tFetch={tFetch}
        userId={session.user?.id}
        accessToken={session.access_token}
        onComplete={(updatedData, csData, ratesData) => {
          setMyTenants(prev => prev.map(t => t.tenantId===currentTenantId ? {...t, data: updatedData, companyName: updatedData.companyName} : t));
          if (csData) setCompanySettings(prev => ({...prev, ...csData}));
          if (ratesData) setRates(prev => ({...prev, ...ratesData}));
        }}
      />
    );
  }

  if (loading) return (
    <div style={{...S.app, height:"100svh", minHeight:"100svh", alignItems:"center", justifyContent:"center"}}>
      <div style={{textAlign:"center", padding:"0 40px"}}>
        <img
          src={"data:image/png;base64," + BLACKTOPIQ_LOGO_B64}
          alt="BlacktopIQ"
          style={{width:"100%", maxWidth: isDesktopLayout ? 560 : 420, display:"block", margin:"0 auto"}}
        />
        <div style={{color:C.textMuted, fontSize:13, marginTop:20, letterSpacing:"0.08em"}}>Loading...</div>
      </div>
    </div>
  );

  return (
    <div style={isDesktopLayout ? S.appDesktop : S.app}>
      <TopNav view={view} setView={navigateTo} userRole={userRole} userRoles={userRoles} permissions={permissions} onLogout={handleLogout} iconStyle={iconStyle} myTenants={myTenants} currentTenantId={currentTenantId} switchTenant={switchTenant} isPlatformAdmin={isPlatformAdmin} companySettings={companySettings}/>
      {!isDesktopLayout && <TrialBanner tenantData={currentTenant?.data} userRole={userRole} onGoToAccount={() => navigateTo("account")}/>}
      <div style={isDesktopLayout ? S.contentColDesktop : undefined}>
        {isDesktopLayout && <TrialBanner tenantData={currentTenant?.data} userRole={userRole} onGoToAccount={() => navigateTo("account")}/>}
        {offlineQueue.length > 0 && (
          <div style={{background:"#fef3c7", color:"#92400e", fontSize:12, textAlign:"center",
            padding:"6px 12px", display:"flex", alignItems:"center", justifyContent:"center", gap:10}}>
            <LucideIcons.WifiOff size={13} strokeWidth={2}/>
            {offlineQueue.length} unsaved change{offlineQueue.length!==1?"s":""} — waiting for connection
            <button onClick={flushOfflineQueue}
              style={{fontSize:11, fontWeight:700, padding:"2px 10px", borderRadius:6,
                background:"#92400e", color:"#fff", border:"none", cursor:"pointer"}}>
              Retry Now
            </button>
          </div>
        )}
        {syncStatus && (
          <div style={{
            background: syncStatus.startsWith("⚠️") ? "#fee2e2" : "#dcfce7",
            color: syncStatus.startsWith("⚠️") ? C.danger : C.green,
            fontSize:11, textAlign:"center", padding:"3px 0",
          }}>{syncStatus}</div>
        )}
        <div style={S.content}>
        {viewHistory.length > 0 && !["jobdetail","estimate","invoice","costs"].includes(view) && (
          <div style={{display:"flex", justifyContent:"flex-end", padding:"16px 24px 0", boxSizing:"border-box"}}>
            <button onClick={goBack} style={S.btnSecondary}>← Back</button>
          </div>
        )}
        {getAccessLevel(permissions,"home",userRoles)!=="hidden" && <div style={{display: view==="home" ? "block" : "none"}}><HomeView jobs={jobs} crews={crews} userRole={userRole} userRoles={userRoles} userId={session?.user?.id} setCurrentJob={setCurrentJob} setView={navigateTo} rates={rates} tFetch={tFetch} setJobs={setJobs} updateJobById={updateJobById} companySettings={companySettings} accessToken={session?.access_token} tenantId={currentTenantId}/></div>}
        {getAccessLevel(permissions,"jobs",userRoles)!=="hidden" && <div style={{display: view==="jobs" ? "block" : "none"}}><JobsPipelineView jobs={jobs} setJobs={handleSetJobs} setCurrentJob={setCurrentJob} setView={navigateTo} rates={rates} updateJobById={updateJobById} userRole={userRole} userRoles={userRoles} userId={session?.user?.id}/></div>}
        {getAccessLevel(permissions,"jobs",userRoles)!=="hidden" && <div style={{display: view==="myjobs" ? "block" : "none"}}><JobsPipelineView jobs={jobs} setJobs={handleSetJobs} setCurrentJob={setCurrentJob} setView={navigateTo} rates={rates} updateJobById={updateJobById} userRole={userRole} userRoles={userRoles} userId={session?.user?.id} scope="mine" showBackButton/></div>}
        {getAccessLevel(permissions,"schedule",userRoles)!=="hidden" && <div style={{display: view==="schedule" ? "block" : "none"}}><ScheduleView jobs={jobs} setCurrentJob={setCurrentJob} setView={navigateTo} userRole={userRole} userRoles={userRoles} userId={session?.user?.id}/></div>}
        {getAccessLevel(permissions,"zones",userRoles)!=="hidden" && planAllowsTab(currentTenant?.data,"zones") && <div style={{display: view==="zones" ? "block" : "none"}}><ZonesView jobs={jobs} setJobs={setJobs} zones={zones} setZones={setZones} syncZones={syncZones} setCurrentJob={setCurrentJob} setView={navigateTo} homeBase={homeBase} tFetch={tFetch}/></div>}
        {/* ── Job context bar — shared across all job-scoped views ── */}
        {["jobdetail","estimate","invoice","costs"].includes(view) && currentJob && (
          <JobContextBar
            currentJob={currentJob}
            updateJob={updateJob}
            setView={navigateTo}
            view={view}
            permissions={permissions}
            userRoles={userRoles}
            userRole={userRole}
            planData={currentTenant?.data}
            iconStyle={iconStyle}
          />
        )}
        {view==="jobdetail" && <JobDetailView currentJob={currentJob} updateJob={updateJob} deleteJob={deleteJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}} setView={navigateTo} teamUsers={teamUsers} crews={crews} zones={zones} homeBase={homeBase} userRole={userRole} userRoles={userRoles} userId={session?.user?.id} jobs={jobs} companySettings={companySettings} accessToken={session?.access_token} tenantId={currentTenantId} servicesOffered={currentTenant?.data?.servicesOffered||[]} currentUserName={currentUserName}/>}
        {view==="estimate" && getAccessLevel(permissions,"estimate",userRoles)!=="hidden" && <EstimateView currentJob={currentJob} updateJob={updateJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}} syncJob={syncJob}
          canOverridePrice={hasRole(userRoles||[userRole], "owner") || hasRole(userRoles||[userRole], "manager")}
          readOnly={
          getAccessLevel(permissions,"estimate",userRoles)==="view" ||
          (hasRole(userRoles||[userRole], "estimator") && !(hasRole(userRoles||[userRole], "owner") || hasRole(userRoles||[userRole], "manager")) &&
            (currentJob?.readyForReview || !["estimate","draft"].includes(currentJob?.status)))
        }
          canSeeMoney={hasRole(userRoles||[userRole], "owner") || hasRole(userRoles||[userRole], "manager") || hasRole(userRoles||[userRole], "crewlead")}
          companySettings={companySettings} accessToken={session?.access_token} tenantId={currentTenantId}/>}
        {view==="costs"    && getAccessLevel(permissions,"costs",userRoles)!=="hidden" && planAllowsTab(currentTenant?.data,"costs") && <CostsView   currentJob={currentJob} updateJob={updateJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}} expenses={expenses}/>}
        {view==="expenses" && getAccessLevel(permissions,"expenses",userRoles)!=="hidden" && planAllowsTab(currentTenant?.data,"expenses") && <ExpensesView expenses={expenses} addExpense={addExpense} updateExpense={updateExpense} deleteExpense={deleteExpense} vendors={vendors} addVendor={addVendor} deleteVendor={deleteVendor} jobs={jobs} userRole={userRole} currentTenantId={currentTenantId} session={session} addMaterial={addMaterial}/>}
        {view==="invoice"  && getAccessLevel(permissions,"invoice",userRoles)!=="hidden" && <InvoiceView  currentJob={currentJob} updateJob={updateJob} rates={{...DEFAULT_RATES, ...(currentJob?.rates||rates), other:{label:"Other",unit:"flat",rate:0,rateLabel:"flat $"}}} companySettings={companySettings} accessToken={session?.access_token} tenantId={currentTenantId}/>}
        {getAccessLevel(permissions,"labor",userRoles)!=="hidden" && planAllowsTab(currentTenant?.data,"labor") && <div style={{display: view==="labor" ? "block" : "none"}}><LaborView   laborEntries={laborEntries} addLaborEntry={addLaborEntry} deleteLaborEntry={deleteLaborEntry} userRole={userRole} teamUsers={teamUsers} currentUserId={session?.user?.id} offAppWorkers={offAppWorkers}/></div>}
        {getAccessLevel(permissions,"materials",userRoles)!=="hidden" && planAllowsTab(currentTenant?.data,"materials") && <div style={{display: view==="materials" ? "block" : "none"}}><MaterialsView jobs={jobs} materials={materials} addMaterial={addMaterial} deleteMaterial={deleteMaterial} materialSettings={materialSettings} setMaterialSettings={setMaterialSettings} syncMaterialSettings={syncMaterialSettings} stockChecks={stockChecks} addStockCheck={addStockCheck} deleteStockCheck={deleteStockCheck} userRole={userRole}/></div>}
        {getAccessLevel(permissions,"crm",userRoles)!=="hidden" && <div style={{display: view==="crm" ? "block" : "none"}}><CRMView jobs={jobs} rates={rates} customers={customers} addCustomer={addCustomer} updateCustomer={updateCustomer} updateJobById={updateJobById} crmLogs={crmLogs} addCrmLog={addCrmLog} deleteCrmLog={deleteCrmLog} setCurrentJob={setCurrentJob} setView={navigateTo} userRole={userRole}/></div>}
        {getAccessLevel(permissions,"reports",userRoles)!=="hidden" && planAllowsTab(currentTenant?.data,"reports") && <div style={{display: view==="reports" ? "block" : "none"}}><ReportsView  jobs={jobs} rates={rates} setCurrentJob={setCurrentJob} setView={navigateTo} companySettings={companySettings} laborEntries={laborEntries} expenses={expenses} teamUsers={teamUsers} materials={materials} materialSettings={materialSettings}/></div>}
        {view==="rates"    && getAccessLevel(permissions,"rates",userRoles)!=="hidden" && <RatesView   rates={rates} setRates={handleSetRates} currentJob={currentJob} updateJob={updateJob} setCurrentJob={setCurrentJob} currentTenant={currentTenant} onServicesChange={(services) => {
          setMyTenants(prev => prev.map(t => t.tenantId===currentTenantId ? {...t, data: {...t.data, servicesOffered: services}} : t));
          tFetch("tenants?id=eq." + currentTenantId, { method:"PATCH", body:JSON.stringify({ data: {...currentTenant.data, servicesOffered: services} }) });
        }}/>}
        {view==="homebase" && userRole==="owner" && <HomeBaseView homeBase={homeBase} setHomeBase={setHomeBase} syncHomeBase={syncHomeBase} setView={navigateTo}/>}
        {view==="company-settings" && userRole==="owner" && <CompanySettingsView setView={navigateTo} companySettings={companySettings} syncCompanySettings={syncCompanySettings}/>}
        {view==="referral"      && userRole==="owner" && <ReferralView setView={navigateTo} userId={session?.user?.id}/>}
        {view==="help" && getAccessLevel(permissions,"help",userRoles)!=="hidden" && <HelpView tFetch={tFetch} currentTenantId={currentTenantId} session={session} userRole={userRole} accessToken={session?.access_token} currentUserName={currentUserName} currentTenant={currentTenant}/>}
        {view==="request-form"  && userRole==="owner" && <EstimateRequestLinkView setView={navigateTo} currentTenantId={currentTenantId}/>}
        {view==="team"     && (userRole==="owner"||userRole==="manager") && getTenantPlan(currentTenant?.data).userCap > 1 && <TeamView accessToken={session?.access_token} userRole={userRole} tFetch={tFetch} tenantId={currentTenantId} tenantData={currentTenant?.data} offAppWorkers={offAppWorkers} syncOffAppWorkers={syncOffAppWorkers}/>}
        {view==="owner-hub"    && userRole==="owner" && <OwnerHubView setView={navigateTo} iconStyle={iconStyle} syncIconStyle={syncIconStyle} reportSettings={reportSettings} syncReportSettings={syncReportSettings}/>}
        {view==="platform-admin" && isPlatformAdmin && <PlatformAdminView setView={navigateTo} accessToken={session?.access_token} permissions={permissions} setPermissions={setPermissions} syncPermissions={syncPermissions}/>}
        {view==="global-permissions" && isPlatformAdmin && <PermissionsView permissions={permissions} setPermissions={setPermissions} syncPermissions={syncPermissions} setView={navigateTo} readOnly={false}/>}
        {view==="permissions" && userRole==="owner" && <PermissionsView permissions={permissions} setPermissions={setPermissions} syncPermissions={syncPermissions} setView={navigateTo} readOnly={true}/>}
        {view==="account" && <UserSettingsView accessToken={session?.access_token} userId={session?.user?.id} setView={navigateTo} onLogout={handleLogout} tenantData={currentTenant?.data} userRole={userRole} teamUsers={teamUsers}/>}
        {view==="export"   && userRole==="owner" && planAllowsTab(currentTenant?.data,"export") && <ExportView  jobs={jobs} laborEntries={laborEntries} rates={rates} setView={navigateTo} companySettings={companySettings}/>}
        </div>
      </div>
    </div>
  );
}

// ─── Root — subdomain detection ──────────────────────────────────────────────
function Root() {
  const hostname = typeof window !== "undefined" ? window.location.hostname : "";
  const isAdmin = hostname === "admin.blacktopiq.com" || hostname.startsWith("admin.");
  if (isAdmin) return <AdminApp/>;
  return <App/>;
}

export default Root;
